window.CBT_DATA=window.CBT_DATA||{};window.CBT_DATA["written/2025-1"]={"track":"written","round":"2025-1","questions":[{"id":"written-2025-1-1","no":1,"unit":"소프트웨어 설계","q":"UI의 종류 중 멀티 터치(Multi-touch), 동작 인식(Gesture Recog nition) 등과 같이 사용자의 자연스러운 움직임을 인식하여 서로 주고받는 정보를 제공하는 사용자 인터페이스를 뜻하는 것은?","choices":["CLI(Command Line Interface)","NUI(Natural User Interface)","OUI(Organic User Interface)","GUI(Graphical User Interface)"],"ans":2,"exp":{"concept":"사용자 인터페이스(UI)는 사람이 컴퓨터와 주고받는 방식에 따라 나뉜다. 글자 명령을 치면 CLI, 아이콘과 마우스를 쓰면 GUI, 손가락으로 화면을 벌리거나 몸짓·음성처럼 사람의 자연스러운 행동을 그대로 인식하면 NUI다. 스마트폰에서 두 손가락으로 사진을 확대하는 것이 대표적인 NUI의 예다.","choices":[{"verdict":"오답","why":"CLI(Command Line Interface)는 키보드로 명령어를 문자로 입력해 조작하는 인터페이스로, 몸짓 인식과는 관계없다."},{"verdict":"정답","why":"NUI(Natural User Interface)는 멀티 터치, 동작 인식, 음성 인식처럼 사용자의 자연스러운 움직임과 말로 기기를 조작하는 인터페이스다."},{"verdict":"오답","why":"OUI(Organic User Interface)는 모든 사물과 사용자 사이의 상호작용을 위한 인터페이스로, 휘어지는 화면처럼 사물 자체가 입출력 장치가 되는 형태를 말한다."},{"verdict":"오답","why":"GUI(Graphical User Interface)는 아이콘·창·메뉴 같은 그래픽 요소를 마우스나 펜으로 선택해 조작하는 인터페이스다."}],"keywords":[{"term":"CLI","desc":"명령어를 글자로 입력하는 인터페이스"},{"term":"GUI","desc":"아이콘·메뉴를 마우스로 조작하는 그래픽 인터페이스"},{"term":"NUI","desc":"터치·제스처·음성 등 자연스러운 행동으로 조작하는 인터페이스"},{"term":"OUI","desc":"사물 자체가 입출력 장치가 되는 유기적 인터페이스"}],"memo":"Natural은 '자연스러운 몸짓', Organic은 '사물 자체'로 구분해 기억한다."}},{"id":"written-2025-1-2","no":2,"unit":"소프트웨어 설계","q":"N-S(Nassi-Schneiderman) Chart에 관한 설명으로 거리가 먼 것은?","choices":["연속, 선택 및 다중 선택, 반복 등의 제어 논리 구조로 나타낸다.","조건이 복합되어 있는 곳의 처리를 시각적으로 명확하게 식별하는 데 적합하다.","논리의 기술에 중점을 둔 도형식 표현 방법이다.","주로 화살표를 사용해 논리적인 제어 구조로 흐름을 나타낸다."],"ans":4,"exp":{"concept":"N-S 차트(Nassi-Schneiderman Chart)는 순서도의 화살표를 없애고, 사각형 상자 안에 처리 내용을 쌓아 논리 구조를 그리는 도형식 설계 도구다. 순차·선택·다중 선택·반복 구조만 쓰므로 GOTO 같은 임의의 흐름 이동을 표현할 수 없고, 그래서 구조적 프로그래밍에 잘 맞는다. 박스형 차트라고도 부른다.","choices":[{"verdict":"오답","why":"N-S 차트는 연속(순차), 선택 및 다중 선택, 반복의 제어 구조로 논리를 표현하므로 맞는 설명이다."},{"verdict":"오답","why":"선택 구조를 삼각형으로 나눈 상자로 표현하므로 조건이 복합된 부분의 처리를 시각적으로 명확히 식별하는 데 적합하다는 것은 N-S 차트의 특징이다."},{"verdict":"오답","why":"N-S 차트는 논리의 기술에 중점을 둔 도형식 표현 방법이므로 맞는 설명이다."},{"verdict":"정답","why":"N-S 차트는 화살표(GOTO)를 쓰지 않고 상자를 쌓아 흐름을 나타낸다. 화살표로 흐름을 그리는 것은 일반 순서도(Flowchart)다."}],"keywords":[{"term":"N-S 차트","desc":"화살표 없이 상자로 순차·선택·반복을 표현하는 구조적 설계 도구, 박스 다이어그램"},{"term":"구조적 프로그래밍","desc":"순차·선택·반복 세 가지 구조만으로 프로그램을 작성하는 방식"},{"term":"순서도(Flowchart)","desc":"기호와 화살표로 처리 흐름을 그리는 도표"}],"memo":"N-S 차트는 '화살표 없는 상자 그림'이라고 기억하면 화살표 보기를 바로 골라낼 수 있다."}},{"id":"written-2025-1-3","no":3,"unit":"소프트웨어 설계","q":"분산 시스템의 미들웨어(Middleware)에 관한 설명 중 틀린 것은?","choices":["위치 투명성(Location Transparency)을 제공해 준다.","분산 시스템에서 다양한 부분을 관리·통신하고 데이터를 교환하게 해주는 소프트웨어로 볼 수 있다.","분산 시스템의 여러 컴포넌트가 요구하는 재사용 가능한 서비스의 구현을 제공해 준다.","애플리케이션과 사용자 사이에서만 분산 서비스를 제공한다."],"ans":4,"exp":{"concept":"미들웨어(Middleware)는 운영체제와 응용 프로그램 사이, 또는 서로 다른 시스템 사이에 끼어 통신과 데이터 교환을 대신 처리해 주는 소프트웨어다. 서로 다른 언어를 쓰는 두 사람 사이의 통역사처럼, 각 컴포넌트가 상대의 위치나 내부 구조를 몰라도 서비스를 주고받게 해 준다.","choices":[{"verdict":"오답","why":"미들웨어는 상대 컴포넌트가 어느 컴퓨터에 있는지 몰라도 호출할 수 있게 하는 위치 투명성(Location Transparency)을 제공하므로 맞는 설명이다."},{"verdict":"오답","why":"미들웨어는 분산 시스템의 여러 부분을 관리하고 서로 통신·데이터 교환하게 해 주는 소프트웨어이므로 맞는 설명이다."},{"verdict":"오답","why":"트랜잭션 처리, 메시지 전달 등 여러 컴포넌트가 공통으로 필요로 하는 재사용 가능한 서비스를 구현해 제공하므로 맞는 설명이다."},{"verdict":"정답","why":"미들웨어는 응용 프로그램과 응용 프로그램, 응용 프로그램과 운영체제, 클라이언트와 서버 등 다양한 구성 요소 사이에서 서비스를 제공한다. '애플리케이션과 사용자 사이에서만'이라는 한정이 틀렸다."}],"keywords":[{"term":"미들웨어","desc":"서로 다른 시스템·응용 프로그램 사이에서 통신과 데이터 교환을 중계하는 소프트웨어"},{"term":"위치 투명성","desc":"자원이 실제 어디에 있는지 몰라도 이름만으로 접근할 수 있는 성질"},{"term":"분산 시스템","desc":"여러 컴퓨터가 네트워크로 연결되어 하나의 시스템처럼 동작하는 구조"}],"memo":"보기에 '~에서만'처럼 범위를 좁히는 표현이 있으면 틀린 보기일 가능성이 높다."}},{"id":"written-2025-1-4","no":4,"unit":"소프트웨어 설계","q":"럼바우(Rumbaugh)의 객체지향 분석 절차로 가장 바르게 나열된 것은?","choices":["기능 모형 → 동적 모형 → 객체 모형","객체 모형 → 동적 모형 → 기능 모형","객체 모형 → 기능 모형 → 동적 모형","기능 모형 → 객체 모형 → 동적 모형"],"ans":2,"exp":{"concept":"럼바우(Rumbaugh)의 객체 모델링 기법(OMT)은 시스템을 세 가지 관점으로 차례로 분석한다. 먼저 어떤 객체가 있고 어떻게 관계를 맺는지(객체 모델링), 다음으로 시간에 따라 객체 상태가 어떻게 바뀌는지(동적 모델링), 마지막으로 데이터가 어떻게 흘러 처리되는지(기능 모델링)를 그린다.","choices":[{"verdict":"오답","why":"기능 모형부터 시작하는 순서가 아니다. 럼바우 분석은 객체 모형이 가장 먼저다."},{"verdict":"정답","why":"객체 모델링(객체 다이어그램) → 동적 모델링(상태 다이어그램) → 기능 모델링(자료 흐름도) 순서가 럼바우의 분석 절차다."},{"verdict":"오답","why":"객체 모형 다음에는 기능 모형이 아니라 동적 모형이 온다."},{"verdict":"오답","why":"기능 모형이 처음에 오는 순서는 럼바우의 분석 절차와 맞지 않는다."}],"keywords":[{"term":"객체 모델링","desc":"객체와 객체 간 관계를 객체 다이어그램으로 표현"},{"term":"동적 모델링","desc":"시간 흐름에 따른 상태 변화를 상태 다이어그램으로 표현"},{"term":"기능 모델링","desc":"입력에서 출력까지 자료 흐름을 자료 흐름도(DFD)로 표현"},{"term":"OMT","desc":"Object Modeling Technique, 럼바우의 객체지향 분석 기법"}],"memo":"럼바우는 '객·동·기' 순서로 외운다."}},{"id":"written-2025-1-5","no":5,"unit":"소프트웨어 설계","q":"그래픽 표기법을 활용해 소프트웨어 구성 요소를 모델링하는 럼바우 분석 기법에 해당하지 않는 것은?","choices":["기능 모델링","객체 모델링","동적 모델링","분석 모델링"],"ans":4,"exp":{"concept":"럼바우 분석 기법은 그래픽 표기법으로 시스템을 객체 모델링, 동적 모델링, 기능 모델링 세 가지로 나누어 모델링한다. 이 세 가지 외의 이름이 보이면 럼바우 기법에 속하지 않는다.","choices":[{"verdict":"오답","why":"기능 모델링은 자료 흐름도(DFD)로 데이터의 처리 과정을 표현하는 럼바우의 모델링 단계다."},{"verdict":"오답","why":"객체 모델링은 객체 다이어그램으로 객체와 관계를 표현하는 럼바우의 첫 단계다."},{"verdict":"오답","why":"동적 모델링은 상태 다이어그램으로 객체의 상태 변화를 표현하는 럼바우의 모델링 단계다."},{"verdict":"정답","why":"분석 모델링은 럼바우 기법의 세 가지 모델링(객체·동적·기능)에 포함되지 않는다."}],"keywords":[{"term":"객체 모델링","desc":"객체 다이어그램 사용"},{"term":"동적 모델링","desc":"상태 다이어그램 사용"},{"term":"기능 모델링","desc":"자료 흐름도(DFD) 사용"}],"memo":"럼바우 모델링은 '객·동·기' 세 개뿐이다. 이름만 그럴듯한 '분석 모델링'에 속지 말자."}},{"id":"written-2025-1-6","no":6,"unit":"소프트웨어 설계","q":"GoF(Gangs of Four) 디자인 패턴 중 구조 패턴에 해당하지 않는 것은?","choices":["Composite","Observer","Decorator","Adapter"],"ans":2,"exp":{"concept":"GoF 디자인 패턴은 목적에 따라 생성·구조·행위 패턴으로 나뉜다. 구조 패턴은 클래스와 객체를 조합해 더 큰 구조를 만드는 패턴이고, 행위 패턴은 객체들이 서로 일을 나누고 통신하는 방법에 관한 패턴이다.","choices":[{"verdict":"오답","why":"Composite는 객체들을 트리 구조로 묶어 부분과 전체를 같은 방식으로 다루게 하는 구조 패턴이다."},{"verdict":"정답","why":"Observer는 한 객체의 상태가 바뀌면 그에 의존하는 객체들에게 자동으로 알리는 행위 패턴이므로 구조 패턴이 아니다."},{"verdict":"오답","why":"Decorator는 객체에 기능을 동적으로 덧붙이는 구조 패턴이다."},{"verdict":"오답","why":"Adapter는 서로 맞지 않는 인터페이스를 연결해 주는 구조 패턴이다."}],"keywords":[{"term":"생성 패턴","desc":"객체 생성 방식에 관한 패턴: Abstract Factory, Builder, Factory Method, Prototype, Singleton"},{"term":"구조 패턴","desc":"클래스·객체 조합에 관한 패턴: Adapter, Bridge, Composite, Decorator, Facade, Flyweight, Proxy"},{"term":"행위 패턴","desc":"객체 간 책임 분배와 통신에 관한 패턴: Observer, Strategy, Command, Iterator, State 등"}],"memo":"구조 패턴 7개는 Adapter, Bridge, Composite, Decorator, Facade, Flyweight, Proxy이다. 이 목록에 없으면 생성 또는 행위 패턴이다."}},{"id":"written-2025-1-7","no":7,"unit":"소프트웨어 설계","q":"프로토타이핑 모형(Prototyping Model)에 관한 설명 중 옳지 않은 것은?","choices":["프로토타이핑을 수행하는 도중에는 새로운 요구사항을 반영할 수 없다.","프로토타입은 발주자와 개발자 모두에게 공동의 참조 모델을 제공한다.","프로토타입은 구현 단계에서 구현 골격이 될 수 있다.","최종 결과물이 완성되기 전에 의뢰자가 최종 결과물의 일부나 모형을 볼 수 있다."],"ans":1,"exp":{"concept":"프로토타이핑 모형(Prototyping Model)은 실제 시스템을 만들기 전에 견본(시제품)을 먼저 만들어 고객에게 보여 주고, 피드백을 받아 요구사항을 다듬어 가는 개발 방법이다. 집을 짓기 전에 모델하우스를 보여 주고 고칠 점을 듣는 것과 비슷하다.","choices":[{"verdict":"정답","why":"프로토타입을 보여 주고 피드백을 받는 과정에서 새로운 요구사항이 나오면 반영하는 것이 이 모형의 핵심이다. 새 요구사항을 반영할 수 없다는 설명은 틀렸다."},{"verdict":"오답","why":"프로토타입은 발주자와 개발자가 함께 보며 이야기하는 공동의 참조 모델이 되므로 맞는 설명이다."},{"verdict":"오답","why":"완성된 프로토타입은 이후 구현 단계에서 구현의 골격으로 활용될 수 있으므로 맞는 설명이다."},{"verdict":"오답","why":"최종 제품이 완성되기 전에 의뢰자가 시제품으로 결과물의 일부나 모형을 미리 볼 수 있으므로 맞는 설명이다."}],"keywords":[{"term":"프로토타이핑 모형","desc":"시제품을 만들어 고객 피드백으로 요구사항을 확정해 가는 개발 모형"},{"term":"프로토타입","desc":"최종 제품의 견본·시제품"},{"term":"요구사항 변경","desc":"프로토타이핑에서는 개발 중 변경을 수용하는 것이 장점"}],"memo":"프로토타이핑의 목적 자체가 요구사항을 끌어내고 바꾸는 것임을 기억하면 '반영할 수 없다'는 말이 틀린 것이 보인다."}},{"id":"written-2025-1-8","no":8,"unit":"소프트웨어 설계","q":"UML에 관한 설명으로 옳지 않은 것은?","choices":["OMG에서 만든 통합 모델링 언어로, 객체 지향적 분석·설계 방법론의 표준 지정을 목표로 한다.","개발자와 고객 또는 개발자 상호 간의 의사 소통을 원활하게 해 준다.","애플리케이션을 개발할 때 쉽게 이해할 수 있도록 돕는 여러 가지 유형의 다이어그램을 제공한다.","실시간 시스템이나 분산 시스템과 같은 시스템의 분석 및 설계에는 사용될 수 없다."],"ans":4,"exp":{"concept":"UML(Unified Modeling Language)은 OMG(Object Management Group)가 표준으로 채택한 객체지향 모델링 언어다. 클래스·시퀀스·상태 다이어그램 등 여러 종류의 그림으로 시스템을 표현해 개발자와 고객이 같은 그림을 보고 소통하게 해 준다.","choices":[{"verdict":"오답","why":"UML은 OMG가 표준으로 채택한 통합 모델링 언어로, 객체지향 분석·설계 방법론의 표준 표기법이 되는 것을 목표로 하므로 맞는 설명이다."},{"verdict":"오답","why":"공통된 다이어그램 표기로 개발자와 고객, 개발자끼리의 의사소통을 돕는 것이 UML의 주요 목적이므로 맞는 설명이다."},{"verdict":"오답","why":"클래스·유스케이스·시퀀스·상태 다이어그램 등 다양한 다이어그램을 제공하므로 맞는 설명이다."},{"verdict":"정답","why":"UML은 범용 모델링 언어로, 실시간 시스템이나 분산 시스템의 분석·설계에도 사용할 수 있다. 사용될 수 없다는 설명이 틀렸다."}],"keywords":[{"term":"UML","desc":"OMG가 표준화한 객체지향 통합 모델링 언어"},{"term":"OMG","desc":"Object Management Group, UML 표준을 관리하는 단체"},{"term":"다이어그램","desc":"UML에서 시스템을 시각적으로 표현하는 그림 단위"}],"memo":"UML은 범용 표준이므로 '~에는 사용될 수 없다'처럼 쓰임새를 막는 보기는 틀린 것으로 본다."}},{"id":"written-2025-1-9","no":9,"unit":"소프트웨어 설계","q":"다음 중 애자일 소프트웨어 개발 기법이 추구하는 가치에 해당하지 않는 것은?","choices":["계약 협상보다 고객과의 협업에 더 큰 가치를 둔다.","계획을 따르는 것보다 변화에 대응하는 것에 더 큰 가치를 둔다.","실제 작동하는 소프트웨어보다 이해하기 좋은 문서에 더 큰 가치를 둔다.","프로세스의 도구보다 개인과 상호작용에 더 큰 가치를 둔다."],"ans":3,"exp":{"concept":"애자일(Agile) 선언문은 네 가지 가치를 제시한다. 공정과 도구보다 개인과 상호작용을, 포괄적인 문서보다 작동하는 소프트웨어를, 계약 협상보다 고객과의 협력을, 계획을 따르기보다 변화에 대응하기를 더 중시한다.","choices":[{"verdict":"오답","why":"계약 협상보다 고객과의 협업을 중시하는 것은 애자일 선언문의 가치다."},{"verdict":"오답","why":"계획을 따르기보다 변화에 대응하는 것을 중시하는 것은 애자일 선언문의 가치다."},{"verdict":"정답","why":"애자일은 포괄적인 문서보다 실제 작동하는 소프트웨어를 더 중시한다. 이 보기는 앞뒤가 뒤바뀌었다."},{"verdict":"오답","why":"공정과 도구보다 개인과 상호작용을 중시하는 것은 애자일 선언문의 가치다."}],"keywords":[{"term":"애자일 선언문","desc":"2001년 발표된 애자일 개발의 4가지 가치와 12가지 원칙"},{"term":"작동하는 소프트웨어","desc":"애자일이 문서보다 중시하는 결과물"},{"term":"XP·스크럼","desc":"대표적인 애자일 개발 방법론"}],"memo":"애자일 가치는 '사람, 작동하는 SW, 고객 협력, 변화 대응'이 앞쪽(더 중요)이다. 문서·계획·계약·도구가 앞에 오면 틀린 보기다."}},{"id":"written-2025-1-10","no":10,"unit":"소프트웨어 설계","q":"자료 흐름도(DFD)의 각 요소와 표기 형태를 연결한 것 중 옳지 않은 것은?","choices":["Data Store : 삼각형","Process : 원","Terminator : 사각형","Data Flow : 화살표"],"ans":1,"exp":{"concept":"자료 흐름도(DFD, Data Flow Diagram)는 데이터가 어디서 들어와 어떤 처리를 거쳐 어디에 저장되는지를 네 가지 기호로 그린다. 처리(Process)는 원, 자료 흐름(Data Flow)은 화살표, 자료 저장소(Data Store)는 위아래 평행선, 단말(Terminator)은 사각형이다.","choices":[{"verdict":"정답","why":"자료 저장소(Data Store)는 삼각형이 아니라 위아래 두 줄의 평행선(=)으로 표시한다."},{"verdict":"오답","why":"처리(Process)는 원(버블)으로 표시하므로 맞는 연결이다."},{"verdict":"오답","why":"단말(Terminator)은 사각형으로 표시하므로 맞는 연결이다."},{"verdict":"오답","why":"자료 흐름(Data Flow)은 화살표로 표시하므로 맞는 연결이다."}],"keywords":[{"term":"Process","desc":"원으로 표시, 입력 데이터를 출력 데이터로 바꾸는 처리"},{"term":"Data Flow","desc":"화살표로 표시, 데이터의 이동"},{"term":"Data Store","desc":"평행선으로 표시, 데이터가 저장되는 곳"},{"term":"Terminator","desc":"사각형으로 표시, 시스템 외부의 데이터 출처·목적지"}],"memo":"DFD 기호는 '원·화살표·평행선·사각형' 네 가지뿐이고 삼각형은 없다."}},{"id":"written-2025-1-11","no":11,"unit":"소프트웨어 설계","q":"객체에게 어떤 행위를 수행하도록 지시하는 명령을 무엇이라 하는가?","choices":["Message","Object","Class","Package"],"ans":1,"exp":{"concept":"객체지향에서 객체들은 서로 메시지(Message)를 보내 일을 시킨다. 메시지를 받은 객체는 자기에게 정의된 메소드를 실행해 그 요청을 처리한다. 리모컨 버튼을 누르는 것이 TV라는 객체에 메시지를 보내는 것과 같다.","choices":[{"verdict":"정답","why":"메시지(Message)는 객체에게 어떤 행위(메소드)를 수행하라고 지시하는 명령 또는 요구 사항이다."},{"verdict":"오답","why":"객체(Object)는 데이터와 그 데이터를 처리하는 함수(메소드)를 묶은 하나의 실체로, 지시하는 명령이 아니라 명령을 받는 대상이다."},{"verdict":"오답","why":"클래스(Class)는 공통 속성과 연산을 가진 객체들을 만들기 위한 틀(설계도)이다."},{"verdict":"오답","why":"패키지(Package)는 관련된 클래스나 요소를 묶어 놓은 그룹이다."}],"keywords":[{"term":"메시지","desc":"객체에게 행위 수행을 요청하는 명령"},{"term":"메소드","desc":"객체가 수행하는 연산, 메시지를 받으면 실행됨"},{"term":"클래스","desc":"같은 성격의 객체를 만드는 틀"},{"term":"인스턴스","desc":"클래스로부터 생성된 실제 객체"}],"memo":"객체에 '일을 시키는 것'은 메시지, 시켜서 '실제로 하는 일'은 메소드로 구분한다."}},{"id":"written-2025-1-12","no":12,"unit":"소프트웨어 설계","q":"결합도(Coupling)의 단계를 약한 것에서 강한 것 순으로 가장 옳게 나타낸 것은?","choices":["Control → Data → Stamp → Common → Content","Stamp → Data → Control → Common → Content","Content → Stamp → Control → Common → Data","Data → Stamp → Control → Common → Content"],"ans":4,"exp":{"concept":"결합도(Coupling)는 모듈과 모듈이 서로 얼마나 의존하는지를 나타낸다. 결합도가 약할수록 한 모듈을 고쳐도 다른 모듈에 영향이 적어 좋은 설계다. 약한 것부터 자료(Data), 스탬프(Stamp), 제어(Control), 외부(External), 공통(Common), 내용(Content) 결합도 순서다.","choices":[{"verdict":"오답","why":"제어 결합도(Control)가 자료·스탬프 결합도보다 앞에 있어 약한 순서가 맞지 않는다."},{"verdict":"오답","why":"스탬프 결합도(Stamp)가 자료 결합도(Data)보다 앞에 있다. 가장 약한 것은 자료 결합도다."},{"verdict":"오답","why":"가장 강한 내용 결합도(Content)가 맨 앞에 있어 순서가 완전히 뒤섞였다."},{"verdict":"정답","why":"자료 → 스탬프 → 제어 → 공통 → 내용 순으로, 외부 결합도는 빠져 있지만 나열된 순서는 약한 것에서 강한 것으로 올바르다."}],"keywords":[{"term":"자료 결합도","desc":"단순한 값(자료)만 주고받는 가장 약한 결합"},{"term":"스탬프 결합도","desc":"배열·구조체 같은 자료 구조를 주고받는 결합"},{"term":"제어 결합도","desc":"다른 모듈의 처리 흐름을 바꾸는 제어 신호(플래그)를 넘기는 결합"},{"term":"공통 결합도","desc":"여러 모듈이 전역 변수를 함께 참조하는 결합"},{"term":"내용 결합도","desc":"다른 모듈의 내부 자료나 코드를 직접 참조하는 가장 강한 결합"}],"memo":"약한 순서는 '자스제외공내'로 외운다."}},{"id":"written-2025-1-13","no":13,"unit":"소프트웨어 설계","q":"HIPO(Hierarchy Input Process Output)에 관한 설명 중 거리가 먼 것은?","choices":["HIPO 차트의 종류로는 가시적 도표, 총체적 도표, 세부적 도표가 있다.","기능과 자료의 의존 관계를 함께 표현할 수 있다.","상향식 소프트웨어 개발을 위해 사용하는 문서화 도구이다.","보기 쉽고 이해하기도 쉽다."],"ans":3,"exp":{"concept":"HIPO(Hierarchy Input Process Output)는 시스템의 기능을 위에서 아래로 나누어 가며 각 기능의 입력·처리·출력을 도표로 정리하는 문서화 도구다. 큰 기능에서 작은 기능으로 내려가는 하향식(Top-Down) 개발에 쓰인다.","choices":[{"verdict":"오답","why":"HIPO 차트는 가시적 도표(전체 기능 계층), 총체적 도표(기능별 입력·처리·출력), 세부적 도표(총체적 도표의 상세)로 구성되므로 맞는 설명이다."},{"verdict":"오답","why":"입력·처리·출력을 함께 보여 주므로 기능과 자료의 의존 관계를 동시에 표현할 수 있다는 것은 맞는 설명이다."},{"verdict":"정답","why":"HIPO는 상향식이 아니라 하향식(Top-Down) 소프트웨어 개발을 위한 문서화 도구다."},{"verdict":"오답","why":"도표 형식이라 보기 쉽고 이해하기 쉬운 것이 HIPO의 장점이므로 맞는 설명이다."}],"keywords":[{"term":"HIPO","desc":"계층적으로 기능의 입력·처리·출력을 표현하는 하향식 문서화 도구"},{"term":"가시적 도표","desc":"Visual Table of Contents, 시스템 전체 기능의 계층 구조"},{"term":"총체적 도표","desc":"Overview Diagram, 각 기능의 입력·처리·출력 개요"},{"term":"세부적 도표","desc":"Detail Diagram, 총체적 도표의 내용을 구체적으로 기술"}],"memo":"HIPO의 H는 Hierarchy(계층)이고, 계층은 위에서 아래로 내려가므로 하향식이다."}},{"id":"written-2025-1-14","no":14,"unit":"소프트웨어 설계","q":"하나의 모듈 안에서 각 구성 요소들이 공통된 목적을 이루기 위해 서로 얼마나 관련되어 있는지, 그 기능적 연관의 정도를 나타내는 것은?","choices":["Unity","Cohesion","Structure","Coupling"],"ans":2,"exp":{"concept":"응집도(Cohesion)는 한 모듈 안의 구성 요소들이 하나의 목적을 위해 얼마나 똘똘 뭉쳐 있는지를 나타낸다. 결합도가 모듈 '사이'의 관계라면 응집도는 모듈 '안'의 관계다. 응집도는 강할수록, 결합도는 약할수록 좋은 설계다.","choices":[{"verdict":"오답","why":"Unity는 소프트웨어 설계에서 모듈 내부의 기능적 연관 정도를 뜻하는 표준 용어가 아니다."},{"verdict":"정답","why":"Cohesion(응집도)은 모듈 내부 구성 요소들이 공통 목적을 위해 기능적으로 관련된 정도를 말한다."},{"verdict":"오답","why":"Structure(구조)는 구성 요소들의 짜임새를 뜻하는 일반적인 말로, 모듈 내부의 기능적 연관 정도를 가리키는 용어가 아니다."},{"verdict":"오답","why":"Coupling(결합도)은 모듈 내부가 아니라 모듈과 모듈 사이의 상호 의존 정도를 나타낸다."}],"keywords":[{"term":"응집도","desc":"모듈 내부 요소들의 기능적 연관 정도, 강할수록 좋음"},{"term":"결합도","desc":"모듈 간 상호 의존 정도, 약할수록 좋음"},{"term":"기능적 응집도","desc":"모듈 내부의 모든 기능이 단일 목적을 위해 수행되는 가장 강한 응집도"}],"memo":"Cohesion은 '안에서 뭉침', Coupling은 '밖과 엮임'으로 구분한다."}},{"id":"written-2025-1-15","no":15,"unit":"소프트웨어 설계","q":"모듈화로 분리된 시스템의 각 기능을 가리키며, 서브루틴, 서브시스템, 소프트웨어 내의 프로그램, 작업 단위 등과 같은 뜻으로 쓰이는 것은?","choices":["Module","Prototype","Component","Things"],"ans":1,"exp":{"concept":"모듈화는 큰 프로그램을 작은 기능 단위로 나누는 것이고, 그렇게 나뉜 각 단위를 모듈(Module)이라 한다. 모듈은 서브루틴, 서브시스템, 작업 단위 등과 같은 뜻으로 쓰이며 독립적으로 컴파일하고 재사용할 수 있다.","choices":[{"verdict":"정답","why":"모듈(Module)은 모듈화로 분리된 시스템의 각 기능 단위로, 서브루틴·서브시스템·작업 단위 등과 같은 의미로 쓰인다."},{"verdict":"오답","why":"프로토타입(Prototype)은 요구사항 확인을 위해 미리 만든 견본(시제품)이다."},{"verdict":"오답","why":"컴포넌트(Component)는 독립적으로 배포·교체할 수 있고 인터페이스를 통해 사용하는 소프트웨어 부품으로, 문제에서 말하는 모듈화로 분리된 기능 단위의 정식 명칭은 모듈이다."},{"verdict":"오답","why":"Things는 UML에서 사물을 가리키는 구성 요소로, 모듈화와 관련된 용어가 아니다."}],"keywords":[{"term":"모듈","desc":"모듈화로 분리된 독립적인 기능 단위"},{"term":"모듈화","desc":"시스템을 기능 단위로 나누어 개발·유지보수를 쉽게 하는 기법"},{"term":"서브루틴","desc":"특정 작업을 수행하도록 분리된 프로그램 일부"}],"memo":"'모듈화로 분리된 것'이라는 문장 자체에 정답 Module이 들어 있다."}},{"id":"written-2025-1-16","no":16,"unit":"소프트웨어 설계","q":"미들웨어(Middleware)에 관한 설명 중 옳지 않은 것은?","choices":["미들웨어의 서비스를 이용하려면 사용자가 정보 교환 방법 등의 내부 동작을 쉽게 확인할 수 있어야 한다.","여러 운영체제에서 응용 프로그램들 사이에 자리하는 소프트웨어이다.","소프트웨어 컴포넌트를 연결하기 위해 준비된 인프라 구조를 제공한다.","여러 컴포넌트를 1 대 1, 1 대 다, 다 대 다 등 다양한 형태로 연결할 수 있다."],"ans":1,"exp":{"concept":"미들웨어는 서로 다른 운영체제와 응용 프로그램 사이에서 통신을 중계하는 소프트웨어다. 사용자는 미들웨어가 내부적으로 어떻게 정보를 주고받는지 몰라도 서비스를 쓸 수 있어야 하는데, 이렇게 복잡한 내부를 감추는 것이 미들웨어의 역할이다.","choices":[{"verdict":"정답","why":"미들웨어는 정보 교환 방법 등 내부 동작을 감추어 사용자가 몰라도 서비스를 이용할 수 있게 해야 한다. 내부 동작을 쉽게 확인할 수 있어야 한다는 설명은 틀렸다."},{"verdict":"오답","why":"미들웨어는 여러 운영체제에서 응용 프로그램들 사이에 위치하는 소프트웨어이므로 맞는 설명이다."},{"verdict":"오답","why":"소프트웨어 컴포넌트를 연결하기 위한 준비된 인프라 구조를 제공하므로 맞는 설명이다."},{"verdict":"오답","why":"1:1, 1:다, 다:다 등 다양한 형태로 컴포넌트를 연결할 수 있으므로 맞는 설명이다."}],"keywords":[{"term":"미들웨어","desc":"운영체제와 응용 프로그램, 또는 시스템 간 통신을 중계하는 소프트웨어"},{"term":"투명성","desc":"사용자가 내부 구조나 위치를 의식하지 않고 서비스를 쓸 수 있는 성질"},{"term":"WAS","desc":"Web Application Server, 동적 웹 서비스를 처리하는 대표적 미들웨어"}],"memo":"미들웨어는 '복잡함을 숨겨 주는 통역사'이므로 내부를 드러내야 한다는 보기는 틀렸다."}},{"id":"written-2025-1-17","no":17,"unit":"소프트웨어 설계","q":"UML의 시퀀스 다이어그램을 구성하는 항목에 해당하지 않는 것은?","choices":["확장","실행","메시지","생명선"],"ans":1,"exp":{"concept":"시퀀스 다이어그램(Sequence Diagram)은 객체들이 시간 순서에 따라 메시지를 주고받는 모습을 그리는 UML 동적 다이어그램이다. 구성 요소는 액터, 객체, 생명선, 실행(활성 상자), 메시지 등이다.","choices":[{"verdict":"정답","why":"확장(extend)은 유스케이스 다이어그램에서 유스케이스 사이의 관계를 나타낼 때 쓰는 것으로, 시퀀스 다이어그램의 구성 항목이 아니다."},{"verdict":"오답","why":"실행(실행 상자, 활성 상자)은 객체가 메시지를 받아 동작하고 있는 구간을 생명선 위의 직사각형으로 표시하는 시퀀스 다이어그램의 구성 항목이다."},{"verdict":"오답","why":"메시지는 객체 사이에 주고받는 호출이나 신호를 화살표로 표시하는 시퀀스 다이어그램의 구성 항목이다."},{"verdict":"오답","why":"생명선(Lifeline)은 객체가 존재하는 기간을 아래로 뻗은 점선으로 표시하는 시퀀스 다이어그램의 구성 항목이다."}],"keywords":[{"term":"생명선","desc":"객체가 존재하는 시간을 나타내는 세로 점선"},{"term":"실행 상자","desc":"객체가 활동 중인 구간을 나타내는 생명선 위 직사각형"},{"term":"메시지","desc":"객체 간 상호작용을 나타내는 화살표"},{"term":"확장(extend)","desc":"유스케이스 다이어그램의 선택적 기능 관계"}],"memo":"'확장·포함'은 유스케이스 다이어그램의 관계라는 점을 묶어서 기억한다."}},{"id":"written-2025-1-18","no":18,"unit":"소프트웨어 설계","q":"럼바우(Rumbaugh)의 객체지향 분석 기법 가운데 자료 흐름도(DFD)를 주로 활용하는 것은?","choices":["객체 모델링","정적 모델링","기능 모델링","동적 모델링"],"ans":3,"exp":{"concept":"럼바우 분석 기법의 세 모델링은 각각 쓰는 그림이 정해져 있다. 객체 모델링은 객체 다이어그램, 동적 모델링은 상태 다이어그램, 기능 모델링은 자료 흐름도(DFD)를 쓴다. 자료 흐름도는 데이터가 처리되며 흘러가는 모습을 그리므로 '기능'과 짝을 이룬다.","choices":[{"verdict":"오답","why":"객체 모델링은 객체 다이어그램으로 객체와 그 관계를 표현한다."},{"verdict":"오답","why":"정적 모델링은 럼바우 분석 기법의 세 가지 모델링에 속하지 않는다."},{"verdict":"정답","why":"기능 모델링은 자료 흐름도(DFD)를 이용해 입력이 출력으로 바뀌는 처리 과정을 표현한다."},{"verdict":"오답","why":"동적 모델링은 상태 다이어그램(상태도)으로 시간에 따른 객체의 상태 변화를 표현한다."}],"keywords":[{"term":"객체 모델링","desc":"객체 다이어그램"},{"term":"동적 모델링","desc":"상태 다이어그램"},{"term":"기능 모델링","desc":"자료 흐름도(DFD)"}],"memo":"'기능은 DFD, 동적은 상태도, 객체는 객체도'로 짝지어 외운다."}},{"id":"written-2025-1-19","no":19,"unit":"소프트웨어 설계","q":"다음 내용이 설명하고 있는 객체지향 설계 원칙은 무엇인가?<div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul><li>클라이언트는 자신이 사용하지 않는 메소드와는 의존관계를 맺어서는 안 된다.</li><li>클라이언트는 사용하지 않는 인터페이스로 인해 영향을 받아서는 안 된다.</li></ul></div>","choices":["인터페이스 분리 원칙","단일 책임 원칙","리스코프 교체의 원칙","개방 폐쇄의 원칙"],"ans":1,"exp":{"concept":"객체지향 설계 원칙 SOLID 중 인터페이스 분리 원칙(ISP)은, 커다란 인터페이스 하나보다 쓰임새별로 잘게 나눈 인터페이스 여러 개가 낫다는 원칙이다. 클라이언트가 자기가 쓰지 않는 메소드 때문에 영향을 받지 않도록 하기 위함이다.","choices":[{"verdict":"정답","why":"인터페이스 분리 원칙(ISP, Interface Segregation Principle)은 클라이언트가 사용하지 않는 메소드와 의존 관계를 맺지 않도록 인터페이스를 분리해야 한다는 원칙으로, 보기의 설명과 같다."},{"verdict":"오답","why":"단일 책임 원칙(SRP)은 하나의 클래스는 하나의 책임만 가져야 한다는 원칙이다."},{"verdict":"오답","why":"리스코프 치환(교체) 원칙(LSP)은 자식 클래스가 부모 클래스를 대신해도 프로그램이 올바르게 동작해야 한다는 원칙이다."},{"verdict":"오답","why":"개방 폐쇄 원칙(OCP)은 기능 확장에는 열려 있고 기존 코드 수정에는 닫혀 있어야 한다는 원칙이다."}],"keywords":[{"term":"SRP","desc":"단일 책임 원칙, 클래스는 하나의 책임만"},{"term":"OCP","desc":"개방 폐쇄 원칙, 확장에 열리고 수정에 닫힘"},{"term":"LSP","desc":"리스코프 치환 원칙, 자식이 부모를 대체 가능"},{"term":"ISP","desc":"인터페이스 분리 원칙, 사용하지 않는 메소드에 의존하지 않음"},{"term":"DIP","desc":"의존 역전 원칙, 구체 클래스가 아닌 추상화에 의존"}],"memo":"지문에 '사용하지 않는 메소드·인터페이스'가 나오면 ISP다."}},{"id":"written-2025-1-20","no":20,"unit":"소프트웨어 설계","q":"LOC 기법으로 예측한 총 라인수가 36000라인이고, 개발에 참여하는 프로그래머가 6명이며, 프로그래머들의 평균 생산성이 월간 300라인이라고 할 때 개발 소요 기간을 계산한 결과로 가장 옳은 것은?","choices":["5개월","10개월","15개월","20개월"],"ans":4,"exp":{"concept":"LOC(Line Of Code) 기법은 전체 코드 줄 수를 예측해 개발 기간과 비용을 계산한다. 개발 기간은 '총 라인 수 ÷ (참여 인원 × 1인당 월 생산성)'으로 구한다.","choices":[{"verdict":"오답","why":"5개월이 되려면 월 생산 라인이 7,200라인이어야 하지만, 실제 팀의 월 생산량은 1,800라인이다."},{"verdict":"오답","why":"10개월이 되려면 월 생산 라인이 3,600라인이어야 하므로 맞지 않는다."},{"verdict":"오답","why":"15개월 동안 만들 수 있는 양은 1,800 × 15 = 27,000라인으로 36,000라인에 못 미친다."},{"verdict":"정답","why":"팀의 월 생산량은 6명 × 300라인 = 1,800라인이고, 36,000 ÷ 1,800 = 20개월이다."}],"keywords":[{"term":"LOC 기법","desc":"원시 코드 라인 수를 비관치·낙관치·기대치로 예측해 비용을 산정하는 기법"},{"term":"노력(MM)","desc":"개발 기간 × 투입 인원, 또는 LOC ÷ 1인당 월 생산성"},{"term":"개발 기간","desc":"노력(MM) ÷ 투입 인원"}],"memo":"먼저 노력 = 36,000 ÷ 300 = 120MM을 구하고, 다시 6명으로 나누면 20개월이다. 인원으로 나누는 것을 잊지 말자."}},{"id":"written-2025-1-21","no":21,"unit":"소프트웨어 개발","q":"코드 인스펙션에 관한 설명으로 옳지 않은 것은?","choices":["코드 품질을 향상시키는 기법 중 하나이다.","결함뿐만 아니라 코딩 표준 준수 여부, 효율성 등 다른 품질 이슈도 검사하기도 한다.","프로그램을 직접 수행시켜보는 대신 읽어보면서 눈으로 확인하는 방법이라고 볼 수 있다.","동적 테스트를 할 때에만 활용하는 기법이다."],"ans":4,"exp":{"concept":"코드 인스펙션(Code Inspection)은 프로그램을 실행하지 않고 여러 사람이 코드를 눈으로 읽으며 결함을 찾는 정적 테스트 기법이다. 원고를 인쇄하기 전에 교정자들이 모여 오탈자를 찾는 것과 비슷하다.","choices":[{"verdict":"오답","why":"코드 인스펙션은 결함을 미리 찾아 코드 품질을 높이는 기법이므로 맞는 설명이다."},{"verdict":"오답","why":"결함뿐 아니라 코딩 표준 준수 여부, 효율성 등 다른 품질 문제도 함께 검사하므로 맞는 설명이다."},{"verdict":"오답","why":"프로그램을 실행하지 않고 코드를 읽어 확인하는 방법이므로 맞는 설명이다."},{"verdict":"정답","why":"코드 인스펙션은 프로그램을 실행하지 않는 정적 테스트 기법이다. 동적 테스트에만 활용한다는 설명이 틀렸다."}],"keywords":[{"term":"정적 테스트","desc":"프로그램을 실행하지 않고 명세서·코드를 검토하는 테스트, 워크스루·인스펙션·동료 검토"},{"term":"동적 테스트","desc":"프로그램을 실행하며 오류를 찾는 테스트, 화이트박스·블랙박스 테스트"},{"term":"코드 인스펙션","desc":"전문가들이 코드를 읽으며 결함을 찾는 공식적인 정적 검토"}],"memo":"인스펙션·워크스루·리뷰는 모두 '읽기만 하는' 정적 테스트다."}},{"id":"written-2025-1-22","no":22,"unit":"소프트웨어 개발","q":"하향식 통합에서 모듈 간 통합 시험을 위해 일시적으로 필요한 조건만 갖추어 임시로 제공하는 시험용 모듈을 무엇이라 하는가?","choices":["Function","Stub","Procedure","Driver"],"ans":2,"exp":{"concept":"통합 테스트에서 아직 만들어지지 않은 모듈 대신 임시로 넣는 가짜 모듈이 필요하다. 하향식 통합은 상위 모듈부터 시험하므로 아직 없는 하위 모듈을 대신하는 스텁(Stub)을, 상향식 통합은 하위 모듈부터 시험하므로 이를 호출해 줄 상위 모듈 대신 드라이버(Driver)를 쓴다.","choices":[{"verdict":"오답","why":"Function(함수)은 특정 기능을 수행하는 코드 단위를 뜻하는 일반 용어로, 통합 시험용 임시 모듈이 아니다."},{"verdict":"정답","why":"스텁(Stub)은 하향식 통합 시험에서 아직 개발되지 않은 하위 모듈을 대신해 필요한 조건만 갖춘 임시 시험용 모듈이다."},{"verdict":"오답","why":"Procedure(프로시저)는 일련의 처리 절차를 묶은 코드 단위로, 통합 시험용 임시 모듈이 아니다."},{"verdict":"오답","why":"드라이버(Driver)는 상향식 통합 시험에서 하위 모듈을 호출하기 위해 상위 모듈을 대신하는 시험용 모듈이다."}],"keywords":[{"term":"스텁(Stub)","desc":"하향식 통합에서 하위 모듈을 대신하는 임시 모듈"},{"term":"드라이버(Driver)","desc":"상향식 통합에서 상위 모듈을 대신하는 임시 모듈"},{"term":"하향식 통합","desc":"상위 모듈에서 하위 모듈 방향으로 통합하며 시험"},{"term":"상향식 통합","desc":"하위 모듈에서 상위 모듈 방향으로 통합하며 시험"}],"memo":"'하향식은 스텁, 상향식은 드라이버'를 서로 바꿔 외우는 실수가 잦다. 위에서 내려가니 아래가 비어 있고, 비어 있는 아래를 메우는 것이 스텁이다."}},{"id":"written-2025-1-23","no":23,"unit":"소프트웨어 개발","q":"제품 소프트웨어의 형상 관리가 하는 역할로 옳지 않은 것은?","choices":["형상 관리를 통해 이전 리버전이나 버전의 정보에 접근할 수 있어 배포본 관리에 유용","불필요한 사용자의 소스 수정을 제한","동일한 프로젝트에 대해 여러 개발자가 동시에 개발 가능","프로젝트 개발비용을 효율적으로 관리"],"ans":4,"exp":{"concept":"형상 관리(SCM, Software Configuration Management)는 소프트웨어 개발 중 생기는 코드·문서 등의 변경 사항을 추적하고 통제하는 활동이다. 누가 언제 무엇을 바꿨는지 기록하고, 이전 버전으로 돌아가거나 여러 개발자가 동시에 작업할 수 있게 해 준다.","choices":[{"verdict":"오답","why":"형상 관리로 이전 리비전이나 버전 정보에 접근할 수 있어 배포본 관리에 유용하므로 맞는 설명이다."},{"verdict":"오답","why":"권한이 없는 사용자의 무분별한 소스 수정을 제한하는 것은 형상 관리의 역할이다."},{"verdict":"오답","why":"변경 이력을 관리하므로 여러 개발자가 같은 프로젝트를 동시에 개발할 수 있게 해 준다."},{"verdict":"정답","why":"프로젝트 개발 비용 관리는 프로젝트 관리(비용 산정·통제)의 영역이며, 형상 관리의 역할이 아니다."}],"keywords":[{"term":"형상 관리","desc":"소프트웨어 변경 사항을 식별·통제·기록·감사하는 활동"},{"term":"형상 통제","desc":"변경 요청을 검토하고 승인해 반영하는 과정"},{"term":"베이스라인","desc":"정식으로 검토·합의되어 변경 통제의 기준이 되는 산출물 상태"}],"memo":"형상 관리는 '변경'과 '버전'을 다룬다. 비용·일정은 다른 관리 영역이다."}},{"id":"written-2025-1-24","no":24,"unit":"소프트웨어 개발","q":"퀵 정렬에 대한 설명으로 옳은 것은?","choices":["레코드의 키 값을 분석하여 같은 값끼리 그 순서에 맞는 버킷에 분배해 두었다가 버킷 순서대로 레코드를 꺼내어 정렬한다.","주어진 파일에서 인접한 두 레코드의 키 값을 비교하여 그 크기에 따라 레코드의 위치를 서로 교환한다.","임의의 레코드 키와 매개변수(h)값만큼 떨어진 위치의 레코드 키를 비교하여 서로 교환해 가며 정렬한다.","레코드의 많은 자료 이동을 없애고 하나의 파일을 부분적으로 나누어 가며 정렬한다."],"ans":4,"exp":{"concept":"퀵 정렬(Quick Sort)은 기준값(피벗, Pivot)을 하나 정해 그보다 작은 값은 왼쪽, 큰 값은 오른쪽으로 나눈 뒤, 나뉜 부분을 같은 방법으로 다시 정렬하는 분할 정복 방식이다. 레코드를 많이 옮기지 않고 파일을 부분적으로 나누어 가며 정렬하는 것이 특징이다.","choices":[{"verdict":"오답","why":"키 값에 따라 버킷에 분배했다가 순서대로 꺼내는 방식은 기수 정렬(Radix Sort)이다."},{"verdict":"오답","why":"인접한 두 레코드를 비교해 교환하는 방식은 버블 정렬(Bubble Sort)이다."},{"verdict":"오답","why":"일정 간격(h)만큼 떨어진 레코드끼리 비교·교환하는 방식은 쉘 정렬(Shell Sort)이다."},{"verdict":"정답","why":"레코드의 많은 자료 이동을 없애고 하나의 파일을 부분적으로 나누어 가며 정렬하는 것은 퀵 정렬의 정의다."}],"keywords":[{"term":"퀵 정렬","desc":"피벗을 기준으로 분할 정복, 평균 O(n log n), 최악 O(n²)"},{"term":"기수 정렬","desc":"자릿수별로 버킷에 분배해 정렬"},{"term":"버블 정렬","desc":"인접 원소를 비교·교환"},{"term":"쉘 정렬","desc":"간격(h)을 두고 삽입 정렬을 반복"}],"memo":"'버킷=기수, 인접=버블, 간격 h=쉘, 나누기=퀵'으로 키워드와 정렬을 짝지어 둔다."}},{"id":"written-2025-1-25","no":25,"unit":"소프트웨어 개발","q":"단위 테스트로 발견할 수 있는 오류에 해당하지 않는 것은 다음 중 무엇인가?","choices":["잘못된 계산 수식으로 인한 틀린 결과","탈출구 없는 반복문을 사용한 경우","모듈 간 비정상적 상호 작용에 따른 원치 않는 결과","알고리즘 오류로 인한 원치 않는 결과"],"ans":3,"exp":{"concept":"단위 테스트(Unit Test)는 모듈 하나를 떼어 내 그 안의 계산, 반복문, 알고리즘이 바르게 동작하는지 확인하는 테스트다. 여러 모듈을 합쳤을 때 서로 데이터를 주고받으며 생기는 문제는 통합 테스트(Integration Test)에서 찾는다.","choices":[{"verdict":"오답","why":"잘못된 계산 수식은 모듈 하나 안의 오류이므로 단위 테스트로 발견할 수 있다."},{"verdict":"오답","why":"탈출 조건이 없는 반복문은 모듈 내부 논리의 오류이므로 단위 테스트로 발견할 수 있다."},{"verdict":"정답","why":"모듈 간 비정상적인 상호 작용으로 생기는 오류는 모듈들을 결합해 시험하는 통합 테스트에서 발견한다."},{"verdict":"오답","why":"알고리즘 오류는 모듈 내부의 오류이므로 단위 테스트로 발견할 수 있다."}],"keywords":[{"term":"단위 테스트","desc":"개별 모듈의 기능과 내부 논리를 검사"},{"term":"통합 테스트","desc":"모듈을 결합해 인터페이스와 상호 작용을 검사"},{"term":"시스템 테스트","desc":"통합된 시스템 전체가 요구사항을 만족하는지 검사"}],"memo":"'모듈 간', '인터페이스'라는 말이 나오면 단위가 아니라 통합 테스트다."}},{"id":"written-2025-1-26","no":26,"unit":"소프트웨어 개발","q":"다음 중 디지털 저작권 관리(DRM) 기술과 거리가 먼 것은?","choices":["라이선스 발급 및 관리","콘텐츠 암호화 및 키 관리","콘텐츠 식별체계 표현","콘텐츠 오류 감지 및 복구"],"ans":4,"exp":{"concept":"디지털 저작권 관리(DRM, Digital Rights Management)는 디지털 콘텐츠를 허가된 사용자만 허가된 범위 안에서 쓰도록 보호하는 기술이다. 콘텐츠를 암호화하고, 키와 라이선스를 발급·관리하며, 콘텐츠를 식별하고 권리를 표현하는 기술 등으로 이루어진다.","choices":[{"verdict":"오답","why":"라이선스 발급 및 관리는 사용 권한을 부여하는 DRM의 핵심 기능으로, 클리어링 하우스(Clearing House)가 담당한다."},{"verdict":"오답","why":"콘텐츠 암호화와 암호 키 관리는 DRM의 기본 기술이다."},{"verdict":"오답","why":"콘텐츠를 고유하게 식별하는 식별 체계 표현은 DRM 기술 요소에 포함된다."},{"verdict":"정답","why":"콘텐츠 오류 감지 및 복구는 데이터 전송·저장의 신뢰성을 위한 기술로, 저작권 보호를 위한 DRM 기술과는 거리가 멀다."}],"keywords":[{"term":"DRM","desc":"디지털 콘텐츠의 불법 복제·사용을 막는 저작권 보호 기술"},{"term":"클리어링 하우스","desc":"라이선스 발급과 사용 권한·결제를 관리하는 곳"},{"term":"패키저","desc":"콘텐츠를 메타데이터와 함께 암호화된 배포 단위로 묶는 도구"},{"term":"크랙 방지(Tamper Resistance)","desc":"크랙에 의한 콘텐츠 무단 사용을 막는 기술"}],"memo":"DRM은 '보호(암호화·키·라이선스·식별)'에 관한 것이다. 오류 복구는 통신·저장 기술이다."}},{"id":"written-2025-1-27","no":27,"unit":"소프트웨어 개발","q":"다음과 같은 제어흐름 그래프에서 McCabe의 cyclomatic 수는 얼마인가?<img class=\"q-img\" src=\"data/img/c91e93e48cc4b3e5ed7ac243bdfeb259.png\" width=\"494\" alt=\"문항 원본 자료\">","choices":["3","4","5","6"],"ans":2,"exp":{"concept":"McCabe의 순환 복잡도(Cyclomatic Complexity)는 제어 흐름 그래프에서 서로 독립적인 실행 경로가 몇 개인지를 나타낸다. 공식은 V(G) = E - N + 2로, E는 화살표(간선) 수, N은 노드 수다.","choices":[{"verdict":"오답","why":"3이 되려면 간선이 5개여야 하지만, 그래프의 간선은 6개다."},{"verdict":"정답","why":"간선은 a→b, a→c, b→c, c→d, d→a, d→c로 6개, 노드는 a, b, c, d로 4개다. V(G) = 6 - 4 + 2 = 4이다."},{"verdict":"오답","why":"5는 간선이 7개일 때의 값으로, 그래프의 간선 수와 맞지 않는다."},{"verdict":"오답","why":"6은 간선 수 자체를 답으로 고른 경우로, 노드 수를 빼고 2를 더하는 공식을 적용하지 않은 값이다."}],"keywords":[{"term":"순환 복잡도","desc":"V(G) = E - N + 2, 독립 경로의 수"},{"term":"E","desc":"제어 흐름 그래프의 간선(화살표) 수"},{"term":"N","desc":"제어 흐름 그래프의 노드 수"},{"term":"기초 경로 검사","desc":"순환 복잡도만큼의 독립 경로를 테스트하는 화이트박스 기법"}],"memo":"간선을 셀 때 곡선 화살표(d→c)를 빠뜨리기 쉽다. 그림의 모든 화살표 머리를 하나씩 세자."}},{"id":"written-2025-1-28","no":28,"unit":"소프트웨어 개발","q":"ISO/IEC 9126에서 정의한 소프트웨어 품질 특성 가운데 기능성(Functionality)의 하위 특성에 해당하지 않는 것은?","choices":["보안성","정확성","적합성","학습성"],"ans":4,"exp":{"concept":"ISO/IEC 9126은 소프트웨어 품질 특성을 기능성, 신뢰성, 사용성, 효율성, 유지보수성, 이식성의 여섯 가지로 나누고, 각각에 하위 특성을 둔다. 기능성의 하위 특성은 적합성, 정확성, 상호운용성, 보안성, 준수성이다.","choices":[{"verdict":"오답","why":"보안성(Security)은 허가되지 않은 접근을 막는 능력으로, 기능성의 하위 특성이다."},{"verdict":"오답","why":"정확성(Accuracy)은 올바른 결과를 내는 능력으로, 기능성의 하위 특성이다."},{"verdict":"오답","why":"적합성(Suitability)은 지정된 작업에 알맞은 기능을 제공하는 능력으로, 기능성의 하위 특성이다."},{"verdict":"정답","why":"학습성(Learnability)은 사용자가 쉽게 배울 수 있는 정도로, 기능성이 아니라 사용성(Usability)의 하위 특성이다."}],"keywords":[{"term":"기능성","desc":"적합성·정확성·상호운용성·보안성·준수성"},{"term":"사용성","desc":"이해성·학습성·운용성·친밀성(매력성)·준수성"},{"term":"ISO/IEC 9126","desc":"소프트웨어 품질 특성과 평가 기준에 관한 국제 표준"}],"memo":"'배우기 쉽다'는 사용하는 사람 입장이므로 사용성에 속한다."}},{"id":"written-2025-1-29","no":29,"unit":"소프트웨어 개발","q":"다음 설명에 해당하는 소프트웨어 버전 관리 도구의 방식은?<div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul><li>버전 관리 자료가 원격 저장소와 로컬 저장소에 함께 저장되어 관리된다.</li><li>로컬 저장소에서도 버전 관리가 가능하므로 원격 저장소에 문제가 생기더라도 로컬 저장소의 자료를 이용해 작업할 수 있다.</li><li>대표적인 버전 관리 도구로는 Git이 있다.</li></ul></div>","choices":["클라이언트·서버 방식","분산 저장소 방식","단일 저장소 방식","공유 폴더 방식"],"ans":2,"exp":{"concept":"버전 관리 도구는 저장소를 어디에 두느냐에 따라 공유 폴더 방식, 클라이언트/서버 방식, 분산 저장소 방식으로 나뉜다. 분산 저장소 방식은 원격 저장소 내용을 개발자마다 로컬 저장소로 통째로 복제해 두므로, 서버가 고장 나도 로컬에서 작업과 이력 확인을 계속할 수 있다.","choices":[{"verdict":"오답","why":"클라이언트/서버 방식은 버전 관리 자료가 중앙 서버 한 곳에만 저장되는 방식으로, CVS, SVN이 대표적이다."},{"verdict":"정답","why":"분산 저장소 방식은 원격 저장소와 로컬 저장소에 모두 버전 자료가 저장되어 로컬에서도 버전 관리가 가능하며, Git이 대표적이다."},{"verdict":"오답","why":"단일 저장소 방식은 버전 관리 도구 방식의 표준 분류가 아니다."},{"verdict":"오답","why":"공유 폴더 방식은 버전 관리 자료를 로컬 컴퓨터의 공유 폴더에 저장해 관리하는 방식으로, RCS, SCCS가 대표적이다."}],"keywords":[{"term":"공유 폴더 방식","desc":"공유 폴더에 자료를 저장, RCS·SCCS"},{"term":"클라이언트/서버 방식","desc":"중앙 서버에 자료를 저장, CVS·SVN"},{"term":"분산 저장소 방식","desc":"원격과 로컬 저장소 모두에 저장, Git·Bazaar"}],"memo":"Git이 보이면 분산 저장소, SVN이 보이면 클라이언트/서버 방식이다."}},{"id":"written-2025-1-30","no":30,"unit":"소프트웨어 개발","q":"아래 트리를 INORDER로 운행한 결과로 옳은 것은?<img class=\"q-img\" src=\"data/img/3893c8f875f1801a5646e318684ea3ea.png\" width=\"494\" alt=\"문항 원본 자료\">","choices":["D B E C F A","A B D C E F","A B C D E F","D B A E C F"],"ans":4,"exp":{"concept":"중위 순회(Inorder)는 '왼쪽 서브트리 → 루트 → 오른쪽 서브트리' 순으로 노드를 방문한다. 그림의 트리는 A가 루트이고, A의 왼쪽 자식은 B(B의 왼쪽 자식 D), 오른쪽 자식은 C(C의 자식 E, F)다.","choices":[{"verdict":"오답","why":"D B E C F A는 루트 A를 맨 마지막에 방문하는 순서로, 중위 순회 결과가 아니다."},{"verdict":"오답","why":"A B D C E F는 루트를 먼저 방문하는 전위 순회(Preorder) 결과다."},{"verdict":"오답","why":"A B C D E F는 위층부터 차례로 방문하는 레벨 순서로, 중위 순회 결과가 아니다."},{"verdict":"정답","why":"A의 왼쪽 서브트리(B)에서 D → B, 루트 A, 오른쪽 서브트리(C)에서 E → C → F를 방문하므로 D B A E C F다."}],"keywords":[{"term":"전위 순회(Preorder)","desc":"루트 → 왼쪽 → 오른쪽"},{"term":"중위 순회(Inorder)","desc":"왼쪽 → 루트 → 오른쪽"},{"term":"후위 순회(Postorder)","desc":"왼쪽 → 오른쪽 → 루트"}],"memo":"전·중·후는 '루트를 언제 방문하느냐'다. 중위는 루트가 가운데 온다."}},{"id":"written-2025-1-31","no":31,"unit":"소프트웨어 개발","q":"소프트웨어 재사용을 통해 얻을 수 있는 이점과 가장 거리가 먼 것은?","choices":["새로운 개발 방법론 도입 용이","프로젝트 문서 공유","생산성 증가","소프트웨어 품질 향상"],"ans":1,"exp":{"concept":"소프트웨어 재사용(Reuse)은 이미 만들어진 소프트웨어의 일부나 전체를 다른 개발에 다시 쓰는 것이다. 개발 시간과 비용이 줄고, 검증된 부품을 쓰므로 품질과 생산성이 오르며, 문서도 공유할 수 있다. 반면 기존 구성 요소에 맞춰야 하므로 새로운 개발 방법론을 도입하기는 오히려 어렵다.","choices":[{"verdict":"정답","why":"재사용은 기존 소프트웨어를 그대로 활용하므로 새로운 개발 방법론 도입은 오히려 어려워진다. 재사용의 이점으로 볼 수 없다."},{"verdict":"오답","why":"재사용하는 소프트웨어의 프로젝트 문서도 함께 공유할 수 있으므로 재사용의 이점이다."},{"verdict":"오답","why":"이미 만든 부품을 다시 쓰므로 개발 시간이 줄고 생산성이 증가한다."},{"verdict":"오답","why":"이미 검증된 모듈을 쓰므로 소프트웨어 품질이 향상된다."}],"keywords":[{"term":"소프트웨어 재사용","desc":"기존 소프트웨어의 기능·모듈을 다른 개발에 다시 활용하는 것"},{"term":"재사용 이점","desc":"개발 시간·비용 단축, 생산성·품질 향상, 프로젝트 실패 위험 감소, 문서 공유"},{"term":"재사용 단점","desc":"새로운 개발 방법론 도입이 어려움, 공통 모듈 작성의 추가 비용"}],"memo":"재사용은 '옛것을 다시 쓰는 것'이므로 '새로운 방법론'과는 반대 방향이다."}},{"id":"written-2025-1-32","no":32,"unit":"소프트웨어 개발","q":"SW 패키징 도구를 활용할 때의 고려사항으로 거리가 먼 것은?","choices":["패키징된 SW는 사용자에게 배포되므로 보안을 고려한다.","보안상 단일 기종에서만 사용 가능하도록 해야 한다.","제품 SW 종류에 적합한 암호화 알고리즘을 적용한다.","사용자 편의성을 위해 복잡성 및 비효율성 문제를 고려한다."],"ans":2,"exp":{"concept":"소프트웨어 패키징은 개발이 끝난 소프트웨어를 사용자에게 배포할 수 있는 형태로 묶는 작업이다. 패키징 도구를 쓸 때는 배포되는 제품의 보안(암호화)과 사용자 편의성을 함께 고려하고, 다양한 이기종 환경에서 연동되도록 해야 한다.","choices":[{"verdict":"오답","why":"패키징된 소프트웨어는 사용자에게 배포되므로 보안을 고려해야 한다는 것은 맞는 고려사항이다."},{"verdict":"정답","why":"패키징 도구 활용 시에는 다양한 이기종 콘텐츠·단말과의 연동을 고려해야 한다. 단일 기종에서만 사용하도록 제한하는 것은 고려사항과 거리가 멀다."},{"verdict":"오답","why":"제품 소프트웨어의 종류에 맞는 암호화 알고리즘을 적용해야 한다는 것은 맞는 고려사항이다."},{"verdict":"오답","why":"보안을 위해 사용자 편의성을 해치지 않도록 복잡성과 비효율성 문제를 고려해야 한다는 것은 맞는 고려사항이다."}],"keywords":[{"term":"소프트웨어 패키징","desc":"개발된 소프트웨어를 배포 가능한 형태로 묶는 작업"},{"term":"패키징 도구","desc":"배포를 위한 패키징 시 디지털 콘텐츠의 지식재산권을 보호·관리하는 도구"},{"term":"이기종 연동","desc":"서로 다른 종류의 단말·시스템에서도 함께 동작하도록 하는 것"}],"memo":"패키징 고려사항은 '보안, 암호화 알고리즘, 이기종 연동, 사용자 편의성'이다."}},{"id":"written-2025-1-33","no":33,"unit":"소프트웨어 개발","q":"다음 트리 구조 가운데 최악의 경우 검색 효율이 가장 떨어지는 것은?","choices":["이진 탐색 트리","레드-블랙 트리","2-3 트리","AVL 트리"],"ans":1,"exp":{"concept":"이진 탐색 트리(BST)는 왼쪽에 작은 값, 오른쪽에 큰 값을 두는 트리인데, 정렬된 값을 차례로 넣으면 한쪽으로만 길게 늘어진 편향 트리가 되어 검색이 연결 리스트처럼 느려진다(최악 O(n)). 레드-블랙 트리, 2-3 트리, AVL 트리는 높이를 자동으로 맞춰 주는 균형 트리라서 최악에도 O(log n)을 보장한다.","choices":[{"verdict":"정답","why":"이진 탐색 트리는 균형 유지 기능이 없어, 한쪽으로 치우친 최악의 경우 검색 시간이 O(n)이 된다."},{"verdict":"오답","why":"레드-블랙 트리는 노드에 빨강·검정 색을 두고 규칙으로 균형을 유지하는 트리로, 최악에도 O(log n) 검색을 보장한다."},{"verdict":"오답","why":"2-3 트리는 모든 리프 노드가 같은 깊이에 있도록 유지하는 균형 트리로, 최악에도 O(log n) 검색을 보장한다."},{"verdict":"오답","why":"AVL 트리는 모든 노드에서 좌우 서브트리 높이 차가 1 이하가 되도록 회전으로 균형을 맞추는 트리로, 최악에도 O(log n) 검색을 보장한다."}],"keywords":[{"term":"이진 탐색 트리","desc":"왼쪽 < 루트 < 오른쪽, 편향되면 최악 O(n)"},{"term":"AVL 트리","desc":"좌우 높이 차 1 이하를 유지하는 균형 이진 탐색 트리"},{"term":"레드-블랙 트리","desc":"색 규칙으로 균형을 유지하는 이진 탐색 트리"},{"term":"균형 트리","desc":"높이를 log n 수준으로 유지해 최악 검색 시간을 보장하는 트리"}],"memo":"보기 중 '균형을 맞추는 장치가 없는' 트리를 찾으면 된다."}},{"id":"written-2025-1-34","no":34,"unit":"소프트웨어 개발","q":"다음 중 선형 구조에 해당하는 것끼리만 묶인 것은?","choices":["큐, 그래프","큐, 데크","리스트, 그래프","스택, 트리"],"ans":2,"exp":{"concept":"자료 구조는 자료를 한 줄로 나란히 늘어놓는 선형 구조와, 한 자료가 여러 자료와 가지처럼 연결되는 비선형 구조로 나뉜다. 선형 구조에는 배열, 리스트, 스택, 큐, 데크가 있고, 비선형 구조에는 트리와 그래프가 있다.","choices":[{"verdict":"오답","why":"큐는 선형 구조지만 그래프는 비선형 구조다."},{"verdict":"정답","why":"큐(Queue)와 데크(Deque)는 모두 자료가 한 줄로 늘어선 선형 구조다."},{"verdict":"오답","why":"리스트는 선형 구조지만 그래프는 비선형 구조다."},{"verdict":"오답","why":"스택은 선형 구조지만 트리는 비선형 구조다."}],"keywords":[{"term":"선형 구조","desc":"배열, 선형 리스트, 스택, 큐, 데크"},{"term":"비선형 구조","desc":"트리, 그래프"},{"term":"데크(Deque)","desc":"양쪽 끝에서 삽입·삭제가 모두 가능한 선형 구조"}],"memo":"트리나 그래프가 섞인 보기는 바로 지운다."}},{"id":"written-2025-1-35","no":35,"unit":"소프트웨어 개발","q":"다음 설명에 해당하는 테스트 용어는?<div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul><li>테스트 결과가 참인지 거짓인지 판단하기 위해 사전에 정의된 참값을 입력하여 비교하는 기법 및 활동을 말한다.</li><li>종류로는 참, 샘플링, 휴리스틱, 일관성 검사가 있다.</li></ul></div>","choices":["테스트 데이터","테스트 시나리오","테스트 오라클","테스트 케이스"],"ans":3,"exp":{"concept":"테스트 오라클(Test Oracle)은 테스트 결과가 맞는지 틀리는지를 판단하기 위해 미리 정해 둔 참값(기대 결과)과 비교하는 기법이다. 시험지를 채점할 때 쓰는 정답지와 같은 역할을 한다.","choices":[{"verdict":"오답","why":"테스트 데이터는 테스트를 실행할 때 프로그램에 넣는 입력 값이다."},{"verdict":"오답","why":"테스트 시나리오는 여러 테스트 케이스를 실행 순서에 따라 묶어 놓은 문서다."},{"verdict":"정답","why":"테스트 오라클은 사전에 정의된 참값과 결과를 비교해 테스트의 참·거짓을 판단하는 기법으로, 참·샘플링·휴리스틱(추정)·일관성 검사 오라클이 있다."},{"verdict":"오답","why":"테스트 케이스는 입력 값, 실행 조건, 기대 결과 등으로 구성된 하나의 테스트 항목 명세다."}],"keywords":[{"term":"참 오라클","desc":"모든 입력 값에 대해 기대 결과를 제공해 모든 오류를 검출"},{"term":"샘플링 오라클","desc":"특정한 몇 개의 입력 값에 대해서만 기대 결과를 제공"},{"term":"휴리스틱(추정) 오라클","desc":"샘플링 오라클을 개선해 나머지 입력은 추정으로 판단"},{"term":"일관성 검사 오라클","desc":"변경 전후 결과가 같은지 확인"}],"memo":"오라클은 '정답지'로 기억하고, 종류는 '참·샘·휴·일'로 외운다."}},{"id":"written-2025-1-36","no":36,"unit":"소프트웨어 개발","q":"코드의 간결성을 유지하려고 사용하는 지침으로 옳지 않은 것은?","choices":["한 줄에 문장을 최대한 많이 코딩한다.","빈 줄을 두어 선언부와 구현부를 구별한다.","복잡한 논리식과 산술식은 괄호 및 들여쓰기(Indentation)로 명확하게 표현한다.","공백을 활용해 실행문 그룹과 주석을 명확하게 구분한다."],"ans":1,"exp":{"concept":"코드의 간결성은 코드를 읽기 쉽고 단순하게 유지하는 것이다. 한 줄에는 한 문장만 쓰고, 빈 줄과 공백, 들여쓰기로 구역을 나누며, 복잡한 식은 괄호로 명확하게 표현한다.","choices":[{"verdict":"정답","why":"한 줄에 여러 문장을 몰아 쓰면 읽기 어려워진다. 간결성을 위해서는 한 줄에 하나의 문장만 코딩해야 한다."},{"verdict":"오답","why":"빈 줄로 선언부와 구현부를 구별하면 코드 구조가 잘 보이므로 맞는 지침이다."},{"verdict":"오답","why":"복잡한 논리식과 산술식을 괄호와 들여쓰기로 명확하게 표현하는 것은 맞는 지침이다."},{"verdict":"오답","why":"공백을 이용해 실행문 그룹과 주석을 구분하는 것은 맞는 지침이다."}],"keywords":[{"term":"코드 간결성","desc":"읽기 쉽고 단순한 코드를 유지하는 것"},{"term":"들여쓰기(Indentation)","desc":"블록 구조를 드러내기 위해 줄 앞에 공백을 두는 것"},{"term":"소스코드 품질","desc":"가독성, 간결성, 명확성 등을 갖춘 코드의 정도"}],"memo":"'최대한 많이'는 간결함과 반대되는 말이다. 한 줄에 한 문장이 원칙이다."}},{"id":"written-2025-1-37","no":37,"unit":"소프트웨어 개발","q":"소프트웨어 재개발과 비교할 때 소프트웨어 재공학이 갖는 장점과 거리가 먼 것은?","choices":["비용 절감","위험부담 감소","시스템 명세의 오류억제","개발 시간의 증가"],"ans":4,"exp":{"concept":"소프트웨어 재공학(Re-engineering)은 기존 시스템을 버리지 않고 분석·수정해 새 요구에 맞게 개선하는 것이다. 처음부터 다시 만드는 재개발보다 비용이 적게 들고, 위험이 줄며, 개발 시간이 단축되고, 이미 검증된 명세를 쓰므로 명세 오류도 줄어든다.","choices":[{"verdict":"오답","why":"기존 시스템을 활용하므로 새로 만드는 것보다 비용이 절감되는 것은 재공학의 장점이다."},{"verdict":"오답","why":"이미 운영되며 검증된 시스템을 바탕으로 하므로 위험 부담이 감소하는 것은 재공학의 장점이다."},{"verdict":"오답","why":"기존 시스템의 명세를 활용하므로 시스템 명세의 오류를 억제할 수 있는 것은 재공학의 장점이다."},{"verdict":"정답","why":"재공학은 개발 시간을 단축시키는 것이 장점이다. 개발 시간의 증가는 장점이 될 수 없다."}],"keywords":[{"term":"재공학","desc":"기존 소프트웨어를 분석·수정해 기능을 개선하는 것"},{"term":"재공학 과정","desc":"분석 → 재구성 → 역공학 → 이식"},{"term":"역공학","desc":"기존 코드에서 설계 정보나 명세를 거꾸로 추출하는 것"}],"memo":"장점은 모두 '줄어드는 것(비용·위험·시간·오류)'이다. '증가'가 보이면 틀린 보기다."}},{"id":"written-2025-1-38","no":38,"unit":"소프트웨어 개발","q":"다음 중 해싱 함수(Hashing Function)의 종류에 해당하지 않는 것은?","choices":["제산법(Division)","숫자 분석법(Digit Analysis)","제곱법(Mid-Square)","개방주소법(Open Addressing)"],"ans":4,"exp":{"concept":"해싱(Hashing)은 키 값을 해싱 함수에 넣어 저장 위치(주소)를 바로 계산하는 방법이다. 해싱 함수에는 제산법, 제곱법, 폴딩법, 기수 변환법, 대수적 코딩법, 숫자 분석법, 무작위법 등이 있다. 서로 다른 키가 같은 주소로 계산되는 충돌이 생기면 개방 주소법이나 체이닝 같은 충돌 해결 기법을 쓴다.","choices":[{"verdict":"오답","why":"제산법(Division)은 키를 특정한 수(보통 소수)로 나눈 나머지를 주소로 쓰는 해싱 함수다."},{"verdict":"오답","why":"숫자 분석법(Digit Analysis, 계수 분석법)은 키의 각 자릿수 분포를 분석해 고르게 분포된 자릿수를 골라 주소로 쓰는 해싱 함수다."},{"verdict":"오답","why":"제곱법(Mid-Square)은 키를 제곱한 값의 중간 부분을 주소로 쓰는 해싱 함수다."},{"verdict":"정답","why":"개방 주소법(Open Addressing)은 충돌이 발생했을 때 빈 자리를 찾아 저장하는 충돌 해결 기법으로, 해싱 함수가 아니다."}],"keywords":[{"term":"해싱 함수","desc":"키를 주소로 바꾸는 함수: 제산법, 제곱법, 폴딩법, 기수 변환법, 숫자 분석법 등"},{"term":"충돌(Collision)","desc":"서로 다른 키가 같은 주소로 계산되는 현상"},{"term":"개방 주소법","desc":"충돌 시 다른 빈 버킷을 찾아 저장하는 충돌 해결법"},{"term":"체이닝","desc":"충돌한 레코드를 연결 리스트로 이어 저장하는 충돌 해결법"}],"memo":"'~법'이라는 이름만 보고 고르지 말고, 주소를 '계산'하는지(함수) 충돌을 '해결'하는지로 구분한다."}},{"id":"written-2025-1-39","no":39,"unit":"소프트웨어 개발","q":"소프트웨어 설치 매뉴얼에 포함되는 항목으로 적절하지 않은 것은?","choices":["설치 관련 파일","소프트웨어 개발 기간","프로그램 삭제","제품 소프트웨어 개요"],"ans":2,"exp":{"concept":"설치 매뉴얼은 사용자가 소프트웨어를 처음 설치할 때 참고하는 설명서다. 제품 소프트웨어 개요, 설치 관련 파일, 설치 아이콘, 프로그램 삭제 방법, 설치 환경과 절차, 관련 추가 정보 등 설치에 필요한 내용을 담는다.","choices":[{"verdict":"오답","why":"설치에 필요한 파일 목록과 설명인 설치 관련 파일은 설치 매뉴얼에 포함된다."},{"verdict":"정답","why":"소프트웨어 개발 기간은 개발 프로젝트 관리 정보일 뿐, 사용자가 설치하는 데 필요한 내용이 아니므로 설치 매뉴얼 항목이 아니다."},{"verdict":"오답","why":"설치된 프로그램을 제거하는 방법인 프로그램 삭제는 설치 매뉴얼에 포함된다."},{"verdict":"오답","why":"제품의 주요 기능과 UI를 소개하는 제품 소프트웨어 개요는 설치 매뉴얼에 포함된다."}],"keywords":[{"term":"설치 매뉴얼","desc":"사용자가 소프트웨어를 설치하는 과정을 단계별로 설명한 문서"},{"term":"사용자 매뉴얼","desc":"설치 후 소프트웨어 사용 방법을 설명한 문서"},{"term":"설치 매뉴얼 구성","desc":"개요, 설치 관련 파일, 설치 아이콘, 프로그램 삭제, 설치 환경·절차, 관련 추가 정보"}],"memo":"설치 매뉴얼은 '사용자가 설치할 때 필요한 정보'만 담는다는 기준으로 판단한다."}},{"id":"written-2025-1-40","no":40,"unit":"소프트웨어 개발","q":"검증(Validation) 검사 기법 가운데 개발자의 장소에서 사용자가 개발자 앞에서 수행하며, 오류 및 사용상의 문제점을 사용자와 개발자가 함께 확인하며 검사하는 기법은?","choices":["알파 검사","형상 검사","디버깅 검사","자료구조 검사"],"ans":1,"exp":{"concept":"검증(Validation) 검사는 사용자 요구대로 소프트웨어가 만들어졌는지 확인하는 것으로, 알파 검사와 베타 검사가 대표적이다. 알파 검사는 개발자의 장소에서 사용자가 개발자 앞에서 수행하고, 베타 검사는 사용자의 실제 환경에서 개발자 없이 수행한다.","choices":[{"verdict":"정답","why":"알파 검사는 개발자의 장소에서 사용자가 개발자 앞에서 수행하며, 오류와 사용상 문제점을 사용자와 개발자가 함께 확인하는 검사다."},{"verdict":"오답","why":"형상 검사는 구성 요소, 목록, 유지보수에 필요한 사항이 갖추어졌는지 확인하는 검사로, 사용자가 개발자 앞에서 수행하는 검사가 아니다."},{"verdict":"오답","why":"디버깅(Debugging)은 발견된 오류의 원인을 찾아 수정하는 작업으로, 사용자가 수행하는 검증 검사 기법이 아니다."},{"verdict":"오답","why":"자료구조 검사는 검증 검사 기법의 표준 분류가 아니다."}],"keywords":[{"term":"알파 검사","desc":"개발자 장소에서 사용자가 개발자와 함께 수행하는 검사, 통제된 환경"},{"term":"베타 검사","desc":"사용자 장소에서 개발자 없이 실제 사용 환경에서 수행하는 검사"},{"term":"검증(Validation)","desc":"사용자의 요구사항대로 만들어졌는지 확인"}],"memo":"개발자 '앞에서'면 알파, 개발자 '없이'면 베타다."}},{"id":"written-2025-1-41","no":41,"unit":"데이터베이스 구축","q":"데이터 모델의 구성 요소 가운데, 데이터 구조에 따라 개념 세계나 컴퓨터 세계에서 실제로 표현된 값들을 처리하는 작업을 뜻하는 것은?","choices":["Relation","Constraint","Operation","Data Structure"],"ans":3,"exp":{"concept":"데이터 모델은 구조(Structure), 연산(Operation), 제약 조건(Constraint) 세 가지로 이루어진다. 구조는 데이터를 어떤 형태로 담는지, 연산은 그 구조에 담긴 실제 값을 어떻게 처리하는지, 제약 조건은 데이터가 지켜야 할 규칙이 무엇인지다.","choices":[{"verdict":"오답","why":"릴레이션(Relation)은 관계형 모델에서 데이터를 저장하는 표(테이블)로, 데이터 모델의 세 구성 요소 중 하나가 아니다."},{"verdict":"오답","why":"제약 조건(Constraint)은 데이터베이스에 저장될 수 있는 실제 데이터의 논리적인 제약 조건이다."},{"verdict":"정답","why":"연산(Operation)은 데이터베이스에 표현된 값(인스턴스)들을 처리하는 작업으로, 데이터를 조작하는 기본 도구다."},{"verdict":"오답","why":"데이터 구조(Structure)는 논리적으로 표현된 개체 타입들 간의 관계로, 데이터의 구성과 정적 성질을 나타낸다."}],"keywords":[{"term":"구조","desc":"개체 타입 간의 관계, 데이터 구성과 정적 성질"},{"term":"연산","desc":"표현된 값들을 처리하는 작업, 데이터 조작 도구"},{"term":"제약 조건","desc":"저장될 수 있는 데이터의 논리적 제약"}],"memo":"데이터 모델 구성 요소는 '구·연·제' 세 가지다. '처리하는 작업'이면 연산이다."}},{"id":"written-2025-1-42","no":42,"unit":"데이터베이스 구축","q":"속성(attribute)에 관한 설명 중 틀린 것은?","choices":["속성은 파일 구조상의 데이터 항목 또는 데이터 필드에 해당한다.","속성은 데이터베이스를 이루는 가장 작은 논리적 단위이다.","속성의 개수를 “cardinality”라고 부른다.","속성은 개체가 가진 특성을 기술한다."],"ans":3,"exp":{"concept":"관계형 데이터베이스의 테이블(릴레이션)에서 열(Column)을 속성(Attribute), 행(Row)을 튜플(Tuple)이라 한다. 속성의 개수는 차수(Degree), 튜플의 개수는 카디널리티(Cardinality)라고 부른다.","choices":[{"verdict":"오답","why":"속성은 파일 구조의 데이터 항목 또는 데이터 필드에 해당하므로 맞는 설명이다."},{"verdict":"오답","why":"속성은 데이터베이스를 구성하는 가장 작은 논리적 단위이므로 맞는 설명이다."},{"verdict":"정답","why":"속성의 개수는 차수(Degree)라고 한다. 카디널리티(Cardinality)는 튜플의 개수다."},{"verdict":"오답","why":"속성은 개체의 특성이나 상태를 기술하는 것이므로 맞는 설명이다."}],"keywords":[{"term":"속성(Attribute)","desc":"릴레이션의 열, 가장 작은 논리적 단위"},{"term":"튜플(Tuple)","desc":"릴레이션의 행"},{"term":"차수(Degree)","desc":"속성의 개수"},{"term":"카디널리티(Cardinality)","desc":"튜플의 개수"},{"term":"도메인(Domain)","desc":"하나의 속성이 가질 수 있는 원자값들의 집합"}],"memo":"차수(Degree)와 카디널리티(Cardinality)를 바꿔 외우는 실수가 많다. 차수는 열(속성) 개수, 카디널리티는 행(튜플) 개수다."}},{"id":"written-2025-1-43","no":43,"unit":"데이터베이스 구축","q":"player 테이블에 player_name, team_id, height 컬럼이 있다. 다음 SQL문에서 문법적으로 오류가 있는 부분은 어디인가?<pre class=\"q-sql\"><code class=\"language-sql\">(1) SELECT player_name, height\n(2) FROM player\n(3) WHERE team_id = 'korea'\n(4) AND height BETWEEN 170 OR 180;</code></pre>","choices":["(1)","(2)","(3)","(4)"],"ans":4,"exp":{"concept":"BETWEEN 연산자는 'BETWEEN 값1 AND 값2' 형식으로 값1 이상 값2 이하의 범위를 지정한다. 두 값 사이는 반드시 AND로 이어야 하며, OR를 쓰면 문법 오류가 된다.","choices":[{"verdict":"오답","why":"SELECT player_name, height는 조회할 열을 쉼표로 나열한 올바른 문법이다."},{"verdict":"오답","why":"FROM player는 조회 대상 테이블을 지정한 올바른 문법이다."},{"verdict":"오답","why":"WHERE team_id = 'korea'는 문자열 비교 조건을 작은따옴표로 쓴 올바른 문법이다."},{"verdict":"정답","why":"BETWEEN은 'BETWEEN 170 AND 180'으로 써야 한다. 'BETWEEN 170 OR 180'은 문법 오류다."}],"keywords":[{"term":"BETWEEN A AND B","desc":"A 이상 B 이하인 값을 찾는 조건, 양 끝 값 포함"},{"term":"WHERE","desc":"조회할 행을 거르는 조건절"},{"term":"AND/OR","desc":"조건을 동시에 만족/하나라도 만족시키는 논리 연산자"}],"memo":"BETWEEN 뒤에는 짝꿍 AND가 반드시 따라온다."}},{"id":"written-2025-1-44","no":44,"unit":"데이터베이스 구축","q":"데이터 무결성 제약 조건 가운데 “개체 무결성 제약” 조건에 관한 설명으로 옳은 것은?","choices":["기본키를 구성하는 속성은 NULL일 수 없으며, 기본키 값의 조합은 릴레이션 내에서 유일해야 한다.","외래키 값은 참조하는 릴레이션의 기본키 값과 동일해야 한다.","릴레이션은 참조할 수 없는 외래키 값을 가질 수 없다.","릴레이션 내의 튜플들은 각 속성의 도메인에 지정된 값만 가져야 한다."],"ans":1,"exp":{"concept":"무결성 제약 조건은 데이터의 정확성을 지키는 규칙이다. 개체 무결성은 기본키가 NULL이거나 중복될 수 없다는 규칙, 참조 무결성은 외래키가 참조하는 테이블의 기본키에 있는 값이거나 NULL이어야 한다는 규칙, 도메인 무결성은 속성 값이 정해진 도메인 범위 안에 있어야 한다는 규칙이다.","choices":[{"verdict":"정답","why":"기본키를 이루는 속성은 NULL일 수 없고 기본키 값은 릴레이션 안에서 유일해야 한다는 것이 개체 무결성 제약이다."},{"verdict":"오답","why":"외래키 값이 참조하는 릴레이션의 기본키 값과 같아야 한다는 것은 참조 무결성에 관한 설명이다."},{"verdict":"오답","why":"참조할 수 없는 외래키 값을 가질 수 없다는 것은 참조 무결성에 관한 설명이다."},{"verdict":"오답","why":"속성 값이 도메인에 지정된 값이어야 한다는 것은 도메인 무결성에 관한 설명이다."}],"keywords":[{"term":"개체 무결성","desc":"기본키는 NULL과 중복 값을 가질 수 없음"},{"term":"참조 무결성","desc":"외래키는 참조 릴레이션의 기본키 값이거나 NULL"},{"term":"도메인 무결성","desc":"속성 값은 정의된 도메인 범위 내의 값"},{"term":"기본키","desc":"후보키 중 튜플을 대표하도록 선택한 키"}],"memo":"'기본키'가 나오면 개체 무결성, '외래키'가 나오면 참조 무결성, '도메인'이 나오면 도메인 무결성이다."}},{"id":"written-2025-1-45","no":45,"unit":"데이터베이스 구축","q":"다음의 관계 대수 가운데 순수 관계 연산자에 해당하지 않는 것은?","choices":["조인(Join)","프로젝트(Project)","디비전(Division)","차집합(Difference)"],"ans":4,"exp":{"concept":"관계 대수 연산자는 일반 집합 연산자와 순수 관계 연산자로 나뉜다. 일반 집합 연산자는 수학의 집합 연산을 그대로 쓴 것으로 합집합, 교집합, 차집합, 교차곱이 있고, 순수 관계 연산자는 릴레이션 구조에 맞게 고안된 것으로 Select, Project, Join, Division이 있다.","choices":[{"verdict":"오답","why":"조인(Join, ⋈)은 두 릴레이션을 공통 속성으로 합쳐 새 릴레이션을 만드는 순수 관계 연산자다."},{"verdict":"오답","why":"프로젝트(Project, π)는 릴레이션에서 원하는 속성(열)만 추출하는 순수 관계 연산자다."},{"verdict":"오답","why":"디비전(Division, ÷)은 한 릴레이션이 다른 릴레이션의 모든 값과 관련된 튜플을 구하는 순수 관계 연산자다."},{"verdict":"정답","why":"차집합(Difference, −)은 일반 집합 연산자에 속하므로 순수 관계 연산자가 아니다."}],"keywords":[{"term":"Select(σ)","desc":"조건을 만족하는 튜플(행)을 추출"},{"term":"Project(π)","desc":"원하는 속성(열)을 추출"},{"term":"Join(⋈)","desc":"공통 속성으로 두 릴레이션을 결합"},{"term":"Division(÷)","desc":"다른 릴레이션의 모든 값을 포함하는 튜플을 추출"},{"term":"일반 집합 연산자","desc":"합집합(∪), 교집합(∩), 차집합(−), 교차곱(×)"}],"memo":"순수 관계 연산자는 '셀·프·조·디' 네 개다. 집합 이름(합·교·차)이 붙으면 일반 집합 연산자다."}},{"id":"written-2025-1-46","no":46,"unit":"데이터베이스 구축","q":"릴레이션에 관한 설명으로 거리가 먼 것은?","choices":["한 릴레이션에 포함된 튜플들은 모두 서로 상이하다.","튜플의 삽입, 삭제 등의 작업으로 인하여 릴레이션은 시간에 따라 변한다.","한 릴레이션에 포함된 튜플들 사이에는 순서가 존재한다.","애트리뷰트는 논리적으로 더 이상 쪼갤 수 없는 원자값으로 저장된다."],"ans":3,"exp":{"concept":"릴레이션은 튜플들의 집합이다. 수학에서 집합의 원소에 순서가 없고 중복이 없듯이, 릴레이션의 튜플도 서로 달라야 하고 순서가 없다. 또 속성 값은 더 이상 쪼갤 수 없는 원자값이어야 한다.","choices":[{"verdict":"오답","why":"릴레이션의 튜플들은 모두 서로 달라야 하므로(중복 불가) 맞는 설명이다."},{"verdict":"오답","why":"삽입·삭제·갱신으로 튜플이 바뀌므로 릴레이션은 시간에 따라 변하는 동적인 성질을 가진다."},{"verdict":"정답","why":"릴레이션의 튜플들 사이에는 순서가 없다. 순서가 존재한다는 설명이 틀렸다."},{"verdict":"오답","why":"속성 값은 논리적으로 더 이상 쪼갤 수 없는 원자값(Atomic Value)으로 저장되므로 맞는 설명이다."}],"keywords":[{"term":"튜플의 유일성","desc":"릴레이션 안의 튜플은 모두 서로 다름"},{"term":"튜플의 무순서성","desc":"튜플 사이에 순서가 없음"},{"term":"속성의 원자성","desc":"속성 값은 더 쪼갤 수 없는 원자값"},{"term":"속성의 무순서성","desc":"속성들 사이에도 순서가 없음"}],"memo":"릴레이션은 '집합'이라서 튜플에도 속성에도 순서가 없다."}},{"id":"written-2025-1-47","no":47,"unit":"데이터베이스 구축","q":"관계형 데이터베이스에서 아래 설명에 해당하는 키(Key)는 무엇인가?<div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><p>한 릴레이션 안의 속성들의 집합으로 이루어진 키로서, 릴레이션을 구성하는 모든 튜플에 대해 유일성은 만족하지만 최소성은 만족하지 못한다.</p></div>","choices":["후보키","슈퍼키","외래키","대체키"],"ans":2,"exp":{"concept":"키(Key)는 튜플을 구별하는 기준이 되는 속성이다. 유일성은 키 값으로 튜플을 하나만 찾을 수 있는 성질이고, 최소성은 키를 이루는 속성 중 하나라도 빼면 유일성이 깨지는, 꼭 필요한 속성만 있는 성질이다. 슈퍼키는 유일성만 만족하고, 후보키는 유일성과 최소성을 모두 만족한다.","choices":[{"verdict":"오답","why":"후보키(Candidate Key)는 유일성과 최소성을 모두 만족하는 키다."},{"verdict":"정답","why":"슈퍼키(Super Key)는 속성들의 집합으로 구성되어 모든 튜플을 유일하게 식별하지만, 불필요한 속성이 포함될 수 있어 최소성은 만족하지 못한다."},{"verdict":"오답","why":"외래키(Foreign Key)는 다른 릴레이션의 기본키를 참조하는 속성이다."},{"verdict":"오답","why":"대체키(Alternate Key)는 후보키 중 기본키로 선택되지 않은 나머지 키다."}],"keywords":[{"term":"슈퍼키","desc":"유일성만 만족"},{"term":"후보키","desc":"유일성과 최소성을 모두 만족"},{"term":"기본키","desc":"후보키 중 선택된 주키, NULL과 중복 불가"},{"term":"대체키","desc":"기본키를 제외한 나머지 후보키"},{"term":"외래키","desc":"다른 릴레이션의 기본키를 참조하는 속성"}],"memo":"'유일성은 만족, 최소성은 불만족'이라는 문장이 나오면 슈퍼키다."}},{"id":"written-2025-1-48","no":48,"unit":"데이터베이스 구축","q":"트랜잭션의 주요 특성 가운데 하나로, 둘 이상의 트랜잭션이 동시에 병행 실행될 때 어느 한 트랜잭션이 실행되는 동안 다른 트랜잭션의 연산이 끼어들 수 없다는 것을 의미하는 것은?","choices":["Consistency","Isolation","Durability","Log"],"ans":2,"exp":{"concept":"트랜잭션은 데이터베이스에서 한꺼번에 처리되어야 하는 작업 단위로, ACID 네 가지 특성을 가진다. 그중 독립성(Isolation)은 여러 트랜잭션이 동시에 실행되더라도 서로의 중간 결과에 끼어들지 못하게 하여, 각각 혼자 실행되는 것처럼 보이게 하는 성질이다.","choices":[{"verdict":"오답","why":"일관성(Consistency)은 트랜잭션이 성공적으로 끝나면 데이터베이스가 언제나 일관된 상태를 유지해야 한다는 특성이다."},{"verdict":"정답","why":"독립성(Isolation)은 둘 이상의 트랜잭션이 병행 실행될 때 한 트랜잭션 실행 중에 다른 트랜잭션의 연산이 끼어들 수 없다는 특성이다."},{"verdict":"오답","why":"영속성(Durability)은 성공적으로 완료된 트랜잭션의 결과가 시스템이 고장 나더라도 영구적으로 반영되어야 한다는 특성이다."},{"verdict":"오답","why":"로그(Log)는 회복을 위해 트랜잭션의 변경 내용을 기록한 것으로, 트랜잭션의 특성이 아니다."}],"keywords":[{"term":"원자성(Atomicity)","desc":"모두 반영되거나 전혀 반영되지 않아야 함(All or Nothing)"},{"term":"일관성(Consistency)","desc":"실행 후에도 데이터베이스가 일관된 상태 유지"},{"term":"독립성(Isolation)","desc":"동시 실행되는 트랜잭션이 서로 간섭하지 않음"},{"term":"영속성(Durability)","desc":"완료된 결과는 영구적으로 반영"}],"memo":"'끼어들 수 없다', '간섭하지 않는다'는 말이 나오면 Isolation이다."}},{"id":"written-2025-1-49","no":49,"unit":"데이터베이스 구축","q":"A1, A2, A3 3개 속성을 갖는 한 릴레이션에서 A1의 도메인은 3개 값, A2의 도메인은 2개 값, A3의 도메인은 4개 값을 갖는다. 이 릴레이션에 존재할 수 있는 가능한 튜플(Tuple)의 최대 개수는?","choices":["24","12","8","9"],"ans":1,"exp":{"concept":"릴레이션의 튜플은 각 속성에서 도메인 값 하나씩을 골라 만든 조합이다. 그래서 만들 수 있는 서로 다른 튜플의 최대 개수는 각 속성의 도메인 크기를 모두 곱한 값(카티션 곱의 크기)이다.","choices":[{"verdict":"정답","why":"3 × 2 × 4 = 24이므로, 서로 다른 튜플은 최대 24개까지 존재할 수 있다."},{"verdict":"오답","why":"12는 A1과 A3의 도메인 크기만 곱한 값(3 × 4)으로, A2를 빠뜨린 결과다."},{"verdict":"오답","why":"8은 A2와 A3의 도메인 크기만 곱한 값(2 × 4)으로, A1을 빠뜨린 결과다."},{"verdict":"오답","why":"9는 도메인 크기를 모두 더한 값(3 + 2 + 4)으로, 조합의 수는 곱으로 구해야 한다."}],"keywords":[{"term":"도메인","desc":"한 속성이 가질 수 있는 원자값들의 집합"},{"term":"카티션 곱","desc":"각 집합에서 하나씩 골라 만든 모든 조합"},{"term":"튜플","desc":"릴레이션의 행, 속성 값들의 한 조합"}],"memo":"가능한 조합의 수는 '더하기'가 아니라 '곱하기'다."}},{"id":"written-2025-1-50","no":50,"unit":"데이터베이스 구축","q":"뷰(View)에 관한 설명 중 틀린 것은?","choices":["DBA는 보안성 측면에서 뷰를 활용하는 것이 가능하다.","SQL을 사용할 경우 뷰에 대한 삽입, 갱신, 삭제 연산 시 제약 사항이 없다.","하나의 뷰 위에 또 다른 뷰를 정의하는 것이 가능하다.","사용자는 필요한 정보를 요구에 맞게 가공하여 뷰로 만들 수 있다."],"ans":2,"exp":{"concept":"뷰(View)는 하나 이상의 기본 테이블에서 필요한 부분만 뽑아 만든 가상 테이블이다. 실제 데이터를 따로 저장하지 않으므로, 뷰를 통해 삽입·갱신·삭제할 때에는 기본 테이블에 그대로 반영할 수 없는 경우가 있어 제약이 따른다.","choices":[{"verdict":"오답","why":"뷰로 보여 줄 열과 행을 제한하면 민감한 데이터를 숨길 수 있으므로 DBA는 보안 측면에서 뷰를 활용할 수 있다."},{"verdict":"정답","why":"뷰는 기본키가 빠져 있거나 집계·조인 등으로 정의된 경우 삽입·갱신·삭제가 불가능하거나 제한되므로, 제약 사항이 없다는 설명은 틀렸다."},{"verdict":"오답","why":"이미 정의된 뷰를 바탕으로 또 다른 뷰를 정의할 수 있으므로 맞는 설명이다."},{"verdict":"오답","why":"사용자는 필요한 정보만 요구에 맞게 가공해 뷰로 만들 수 있으므로 맞는 설명이다."}],"keywords":[{"term":"뷰(View)","desc":"기본 테이블에서 유도된 가상 테이블"},{"term":"뷰의 장점","desc":"논리적 독립성 제공, 데이터 접근 제어로 보안 강화, 사용자 데이터 관리 단순화"},{"term":"뷰의 단점","desc":"독자적인 인덱스를 가질 수 없음, 정의를 변경(ALTER)할 수 없음, 삽입·삭제·갱신에 제약"}],"memo":"뷰는 '가상' 테이블이므로 변경 연산에 제약이 있다는 점을 꼭 기억한다."}},{"id":"written-2025-1-51","no":51,"unit":"데이터베이스 구축","q":"관계대수에 관한 설명 중 틀린 것은?","choices":["질의에 대한 해를 구하기 위해 수행해야 하는 연산의 순서를 명시한다.","주어진 릴레이션을 조작하기 위한 연산의 집합이다.","일반 집합 연산과 순수 관계 연산으로 나뉜다.","원하는 정보와 그 정보를 어떻게 유도하는지를 기술하는 비절차적 방법이다."],"ans":4,"exp":{"concept":"관계대수(Relational Algebra)는 릴레이션에서 원하는 결과를 얻기 위해 어떤 연산을 어떤 순서로 할지 명시하는 절차적 언어다. 반대로 관계해석(Relational Calculus)은 원하는 결과가 '무엇인지'만 기술하는 비절차적 언어다. 요리법처럼 순서를 적으면 관계대수, 완성된 요리의 모습만 말하면 관계해석이다.","choices":[{"verdict":"오답","why":"관계대수는 질의의 해를 구하기 위해 수행할 연산의 순서를 명시하므로 맞는 설명이다."},{"verdict":"오답","why":"관계대수는 릴레이션을 조작하기 위한 연산의 집합이므로 맞는 설명이다."},{"verdict":"오답","why":"관계대수 연산자는 일반 집합 연산(합·교·차·교차곱)과 순수 관계 연산(Select·Project·Join·Division)으로 나뉘므로 맞는 설명이다."},{"verdict":"정답","why":"관계대수는 정보를 어떻게 유도하는지 순서를 기술하는 절차적 언어다. 비절차적 방법은 관계해석에 대한 설명이다."}],"keywords":[{"term":"관계대수","desc":"원하는 정보를 얻는 연산 순서를 기술하는 절차적 언어"},{"term":"관계해석","desc":"원하는 정보가 무엇인지만 기술하는 비절차적 언어, 코드(E. F. Codd)가 제안"},{"term":"순수 관계 연산자","desc":"Select, Project, Join, Division"}],"memo":"'대수는 절차적, 해석은 비절차적'으로 짝지어 외운다."}},{"id":"written-2025-1-52","no":52,"unit":"데이터베이스 구축","q":"시스템 카탈로그에 관한 설명으로 옳지 않은 것은?","choices":["데이터베이스에 포함된 데이터 객체의 정의나 명세에 관한 정보를 유지관리한다.","DBMS가 스스로 생성하고 유지하는, 데이터베이스 내의 특별한 테이블의 집합체이다.","카탈로그에 저장된 정보를 메타 데이터라고 부르기도 한다.","시스템 카탈로그의 갱신은 무결성 유지를 위해 사용자가 SQL을 이용하여 직접 갱신해야 한다."],"ans":4,"exp":{"concept":"시스템 카탈로그(System Catalog)는 데이터베이스에 있는 테이블, 뷰, 인덱스, 사용자 권한 같은 객체들의 정의 정보를 모아 둔 시스템 데이터베이스다. 이 정보를 데이터에 대한 데이터, 즉 메타데이터라 부른다. 카탈로그는 DBMS가 스스로 만들고 고치며, 사용자는 SQL로 조회만 할 수 있다.","choices":[{"verdict":"오답","why":"카탈로그는 데이터베이스에 포함된 모든 데이터 객체의 정의와 명세 정보를 유지·관리하므로 맞는 설명이다."},{"verdict":"오답","why":"카탈로그는 DBMS가 스스로 생성하고 유지하는 특별한 테이블들의 집합이므로 맞는 설명이다."},{"verdict":"오답","why":"카탈로그에 저장된 정보를 메타데이터(Metadata)라고 하므로 맞는 설명이다."},{"verdict":"정답","why":"카탈로그는 사용자가 SQL로 직접 갱신할 수 없고, 테이블 생성·변경 등이 일어나면 DBMS가 자동으로 갱신한다. 사용자는 SQL로 내용을 검색만 할 수 있다."}],"keywords":[{"term":"시스템 카탈로그","desc":"데이터베이스 객체들의 정의 정보를 담은 시스템 데이터베이스"},{"term":"메타데이터","desc":"데이터에 관한 데이터, 카탈로그에 저장된 정보"},{"term":"데이터 사전(Data Dictionary)","desc":"시스템 카탈로그와 같은 뜻으로 쓰이는 용어"}],"memo":"카탈로그는 '검색은 사용자도, 갱신은 DBMS만'이다."}},{"id":"written-2025-1-53","no":53,"unit":"데이터베이스 구축","q":"트랜잭션 수행 중에 장애가 발생하여 손상된 데이터베이스를 손상 이전의 정상 상태로 되돌리는 작업은?","choices":["Recovery","Restart","Abort","Commit"],"ans":1,"exp":{"concept":"회복(Recovery)은 트랜잭션 실행 중 장애가 나서 데이터베이스가 손상되었을 때, 손상되기 전의 정상 상태로 되돌리는 작업이다. 로그(Log)를 이용해 실행을 취소(Undo)하거나 다시 실행(Redo)해 복구한다.","choices":[{"verdict":"정답","why":"Recovery(회복)는 장애로 손상된 데이터베이스를 손상 이전의 정상 상태로 복구하는 작업이다."},{"verdict":"오답","why":"Restart(재시작)는 시스템이나 트랜잭션을 다시 시작하는 것으로, 손상된 데이터베이스를 정상 상태로 되돌리는 작업 전체를 가리키는 용어가 아니다."},{"verdict":"오답","why":"Abort(철회)는 트랜잭션 실행에 실패해 작업을 취소한 트랜잭션의 상태다."},{"verdict":"오답","why":"Commit(완료)은 트랜잭션이 성공적으로 끝나 변경 내용을 데이터베이스에 영구 반영하는 것이다."}],"keywords":[{"term":"Recovery","desc":"장애로 손상된 DB를 손상 이전의 정상 상태로 복구"},{"term":"Undo","desc":"로그를 이용해 변경 내용을 취소"},{"term":"Redo","desc":"로그를 이용해 변경 내용을 다시 반영"},{"term":"Abort","desc":"실패해 철회된 트랜잭션 상태"}],"memo":"'되돌리는 작업'이라는 질문에는 Recovery가 정답이고, Abort는 '실패한 상태'임을 구분한다."}},{"id":"written-2025-1-54","no":54,"unit":"데이터베이스 구축","q":"릴레이션 R 에서 모든 결정자(Determinant)가 후보키일 때, 그 릴레이션 R은 어느 정규형에 속하는가?","choices":["제 2 정규형","제 1 정규형","보이스/코드 정규형","제 4 정규형"],"ans":3,"exp":{"concept":"결정자(Determinant)는 함수적 종속 X → Y에서 다른 속성 Y를 결정하는 X를 말한다. 보이스/코드 정규형(BCNF)은 릴레이션의 모든 결정자가 후보키여야 한다는 조건으로, 3정규형보다 더 엄격하다.","choices":[{"verdict":"오답","why":"제2정규형(2NF)은 기본키에 대해 부분 함수적 종속을 제거해 완전 함수적 종속을 만족하는 정규형이다."},{"verdict":"오답","why":"제1정규형(1NF)은 모든 속성의 도메인이 원자값만으로 되어 있는 정규형이다."},{"verdict":"정답","why":"보이스/코드 정규형(BCNF)은 결정자이면서 후보키가 아닌 것을 제거해 모든 결정자가 후보키가 되도록 한 정규형이다."},{"verdict":"오답","why":"제4정규형(4NF)은 다치 종속(MVD)을 제거한 정규형이다."}],"keywords":[{"term":"1NF","desc":"도메인이 원자값"},{"term":"2NF","desc":"부분 함수적 종속 제거"},{"term":"3NF","desc":"이행적 함수적 종속 제거"},{"term":"BCNF","desc":"결정자이면서 후보키가 아닌 것 제거"},{"term":"4NF·5NF","desc":"다치 종속 제거·조인 종속 제거"}],"memo":"정규화 순서는 '도부이결다조'(원자값→부분→이행→결정자→다치→조인)로 외운다."}},{"id":"written-2025-1-55","no":55,"unit":"데이터베이스 구축","q":"다음 설명에서 ( ) 안에 들어갈 내용으로 알맞은 것은?<div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><p>후보키는 릴레이션 내의 모든 튜플에 대하여 유일성과 (&nbsp;&nbsp;&nbsp;&nbsp;)을 모두 만족해야 한다.</p></div>","choices":["최소성","참조성","동일성","중복성"],"ans":1,"exp":{"concept":"후보키(Candidate Key)는 튜플을 유일하게 식별할 수 있는 속성 집합 중에서 꼭 필요한 속성만으로 구성된 키다. 그래서 유일성(Unique)과 최소성(Minimality)을 모두 만족해야 한다.","choices":[{"verdict":"정답","why":"후보키는 유일성과 최소성을 모두 만족해야 한다. 최소성은 키를 이루는 속성 중 하나라도 빼면 유일성이 깨지는 성질이다."},{"verdict":"오답","why":"참조성은 키가 만족해야 하는 성질로 쓰이는 용어가 아니다. 다른 릴레이션을 참조하는 것은 외래키의 역할이다."},{"verdict":"오답","why":"동일성은 키의 성질이 아니다. 키는 오히려 튜플들이 서로 다르게 구별되어야 한다."},{"verdict":"오답","why":"중복성은 키가 피해야 하는 성질이다. 키 값은 중복되면 안 된다."}],"keywords":[{"term":"유일성","desc":"키로 하나의 튜플만을 유일하게 식별"},{"term":"최소성","desc":"키를 구성하는 속성이 꼭 필요한 최소한의 것만으로 구성"},{"term":"후보키","desc":"유일성과 최소성을 만족"},{"term":"슈퍼키","desc":"유일성만 만족"}],"memo":"후보키 = 유일성 + 최소성, 슈퍼키 = 유일성만이다."}},{"id":"written-2025-1-56","no":56,"unit":"데이터베이스 구축","q":"시스템의 성능 향상과 개발 운영의 단순화를 위해 정규화된 엔티티, 속성, 관계에 대해 중복, 통합, 분리 등을 수행하는 데이터 모델링 기법은?","choices":["머징","반정규화","정규화","집단화"],"ans":2,"exp":{"concept":"반정규화(Denormalization)는 정규화된 데이터 모델을 성능 향상과 개발·운영의 단순화를 위해 일부러 중복, 통합, 분리하는 기법이다. 정규화로 테이블을 잘게 나누면 조인이 많아져 느려질 수 있으므로, 필요한 곳에서는 다시 합치거나 중복을 허용한다.","choices":[{"verdict":"오답","why":"머징(Merging)은 '병합'을 뜻하는 일반적인 말로, 중복·통합·분리를 수행하는 데이터 모델링 기법의 이름이 아니다."},{"verdict":"정답","why":"반정규화는 시스템 성능 향상과 개발·운영의 단순화를 위해 정규화된 엔티티·속성·관계에 중복, 통합, 분리 등을 수행하는 기법이다."},{"verdict":"오답","why":"정규화(Normalization)는 이상 현상을 없애기 위해 릴레이션을 분해해 중복을 줄이는 과정으로, 반정규화와 반대 방향이다."},{"verdict":"오답","why":"집단화(Aggregation)는 여러 객체나 개체를 묶어 하나의 상위 개체로 표현하는 추상화 개념이다."}],"keywords":[{"term":"반정규화","desc":"성능 향상을 위해 정규화된 모델을 중복·통합·분리하는 기법"},{"term":"정규화","desc":"이상 현상 제거를 위해 릴레이션을 분해하는 과정"},{"term":"반정규화 방법","desc":"테이블 통합·분할, 중복 테이블 추가, 중복 속성 추가"}],"memo":"'성능 향상을 위해 중복을 허용'하면 반정규화다."}},{"id":"written-2025-1-57","no":57,"unit":"데이터베이스 구축","q":"물리적 데이터베이스 설계에 관한 설명 중 거리가 먼 것은?","choices":["물리적 설계의 목적은 데이터를 효율적인 방법으로 저장하는 것이다.","트랜잭션의 인터페이스를 설계하고, 데이터 타입과 데이터 타입들 간의 관계로 표현한다.","저장 레코드의 형식, 순서, 접근 경로 등의 정보를 활용하여 설계한다.","트랜잭션 처리량, 응답시간, 디스크 용량 등을 고려하여야 한다."],"ans":2,"exp":{"concept":"데이터베이스 설계는 요구 조건 분석 → 개념적 설계 → 논리적 설계 → 물리적 설계 → 구현 순서로 진행된다. 논리적 설계는 특정 DBMS에 맞는 스키마와 트랜잭션 인터페이스를 설계하는 단계이고, 물리적 설계는 그 스키마를 실제 저장 장치에 어떻게 저장할지(레코드 형식, 접근 경로, 인덱스 등) 정하는 단계다.","choices":[{"verdict":"오답","why":"물리적 설계의 목적은 데이터를 효율적인 방법으로 저장하는 것이므로 맞는 설명이다."},{"verdict":"정답","why":"트랜잭션의 인터페이스를 설계하고 데이터 타입과 데이터 타입들 간의 관계로 표현하는 것은 논리적 설계 단계의 내용이다."},{"verdict":"오답","why":"저장 레코드의 형식, 순서, 접근 경로 등을 정하는 것은 물리적 설계의 내용이므로 맞는 설명이다."},{"verdict":"오답","why":"물리적 설계에서는 트랜잭션 처리량, 응답 시간, 저장 공간(디스크 용량)의 효율화를 고려해야 하므로 맞는 설명이다."}],"keywords":[{"term":"개념적 설계","desc":"E-R 다이어그램으로 개념 스키마 모델링, 트랜잭션 모델링"},{"term":"논리적 설계","desc":"DBMS에 맞는 논리 스키마 설계, 트랜잭션 인터페이스 설계"},{"term":"물리적 설계","desc":"저장 레코드 형식, 접근 경로, 인덱스 등 물리적 저장 구조 설계"}],"memo":"'트랜잭션' 단어가 나오면 단계 구분에 주의한다. 개념적은 트랜잭션 모델링, 논리적은 트랜잭션 인터페이스 설계, 물리적은 트랜잭션 세부 설계다."}},{"id":"written-2025-1-58","no":58,"unit":"데이터베이스 구축","q":"E-R 모델의 표현 방법 중 옳지 않은 것은?","choices":["개체 타입 : 사각형","속성 : 오각형","관계 타입 : 마름모","연결 : 선"],"ans":2,"exp":{"concept":"E-R 다이어그램은 개체(Entity)와 관계(Relationship)를 그림으로 표현한다. 개체 타입은 사각형, 관계 타입은 마름모, 속성은 타원, 이들을 연결하는 것은 선으로 그린다.","choices":[{"verdict":"오답","why":"개체 타입은 사각형으로 표현하므로 맞는 연결이다."},{"verdict":"정답","why":"속성은 오각형이 아니라 타원으로 표현한다. 기본키 속성은 밑줄 친 타원으로 나타낸다."},{"verdict":"오답","why":"관계 타입은 마름모로 표현하므로 맞는 연결이다."},{"verdict":"오답","why":"개체 타입과 속성, 관계 타입을 연결할 때는 선을 사용하므로 맞는 연결이다."}],"keywords":[{"term":"사각형","desc":"개체 타입"},{"term":"마름모","desc":"관계 타입"},{"term":"타원","desc":"속성, 기본키 속성은 밑줄 타원"},{"term":"이중 타원","desc":"다중값 속성"},{"term":"선","desc":"개체와 속성·관계를 연결"}],"memo":"E-R 기호에 오각형은 없다. '사각형·마름모·타원·선'만 기억한다."}},{"id":"written-2025-1-59","no":59,"unit":"데이터베이스 구축","q":"데이터 속성 간의 종속성을 엄밀히 고려하지 않고 잘못 설계된 데이터베이스에서는 데이터 처리 연산을 수행할 때 각종 이상 현상이 발생할 수 있다. 이러한 이상 현상에 해당하지 않는 것은?","choices":["삭제 이상","검색 이상","갱신 이상","삽입 이상"],"ans":2,"exp":{"concept":"이상(Anomaly) 현상은 정규화가 덜 된 테이블에 중복 데이터가 있을 때, 데이터를 넣거나 지우거나 고칠 때 생기는 문제다. 삽입 이상, 삭제 이상, 갱신 이상 세 가지가 있으며, 조회만 하는 검색은 데이터를 바꾸지 않으므로 이상 현상이 생기지 않는다.","choices":[{"verdict":"오답","why":"삭제 이상은 튜플을 삭제할 때 원치 않는 다른 값들까지 함께 삭제되는 현상이다."},{"verdict":"정답","why":"검색 이상은 이상 현상의 종류에 해당하지 않는다. 이상 현상은 삽입, 삭제, 갱신 세 가지뿐이다."},{"verdict":"오답","why":"갱신 이상은 중복된 튜플 중 일부만 수정되어 데이터가 서로 맞지 않게 되는 현상이다."},{"verdict":"오답","why":"삽입 이상은 데이터를 삽입할 때 원치 않는 값들도 함께 삽입해야 하거나 삽입이 되지 않는 현상이다."}],"keywords":[{"term":"이상 현상","desc":"중복으로 인해 데이터 조작 시 발생하는 예기치 못한 문제"},{"term":"삽입 이상","desc":"원치 않는 값까지 함께 삽입해야 하는 현상"},{"term":"삭제 이상","desc":"원치 않는 값까지 함께 삭제되는 현상"},{"term":"갱신 이상","desc":"일부만 수정되어 데이터 불일치가 생기는 현상"}],"memo":"이상 현상은 '삽·삭·갱' 세 가지이고, 데이터를 바꾸지 않는 검색은 해당하지 않는다."}},{"id":"written-2025-1-60","no":60,"unit":"데이터베이스 구축","q":"다음 중 DCL(Data Control Language) 명령어에 해당하지 않는 것은?","choices":["SELECT","ROLLBACK","GRANT","COMMIT"],"ans":1,"exp":{"concept":"SQL은 기능에 따라 DDL(정의어), DML(조작어), DCL(제어어)로 나뉜다. 정보처리기사 출제 기준에서 DCL은 데이터의 보안과 무결성, 회복, 병행 제어를 위한 명령으로 GRANT, REVOKE, COMMIT, ROLLBACK이 해당한다. COMMIT과 ROLLBACK은 트랜잭션 제어어(TCL)로 따로 분류하기도 한다.","choices":[{"verdict":"정답","why":"SELECT는 테이블에서 데이터를 검색하는 DML(Data Manipulation Language) 명령어이므로 DCL이 아니다."},{"verdict":"오답","why":"ROLLBACK은 트랜잭션의 변경 내용을 취소하는 명령으로, DCL에 포함된다."},{"verdict":"오답","why":"GRANT는 사용자에게 권한을 부여하는 DCL 명령어다."},{"verdict":"오답","why":"COMMIT은 트랜잭션의 변경 내용을 데이터베이스에 영구 반영하는 명령으로, DCL에 포함된다."}],"keywords":[{"term":"DDL","desc":"CREATE, ALTER, DROP"},{"term":"DML","desc":"SELECT, INSERT, UPDATE, DELETE"},{"term":"DCL","desc":"GRANT, REVOKE, COMMIT, ROLLBACK"},{"term":"TCL","desc":"COMMIT, ROLLBACK, SAVEPOINT 등 트랜잭션 제어 명령"}],"memo":"DML은 '검색·삽입·수정·삭제(SELECT·INSERT·UPDATE·DELETE)' 네 개로 외워 두면 나머지를 쉽게 가를 수 있다."}},{"id":"written-2025-1-61","no":61,"unit":"프로그래밍 언어 활용","q":"JAVA의 변수와 자료형에 관한 설명 중 틀린 것은?","choices":["boolean 자료형은 조건이 참인지 거짓인지를 판단할 때 사용한다.","변수는 어떤 값을 주기억장치에 기억해 두기 위해 사용하는 공간이다.","char 자료형은 한 개의 문자를 저장할 때 사용한다.","실수형 자료형으로는 float, short, byte가 있다."],"ans":4,"exp":{"concept":"Java의 기본 자료형은 정수형(byte, short, int, long), 실수형(float, double), 문자형(char), 논리형(boolean)으로 나뉜다. 변수는 값을 주기억장치에 저장해 두기 위한 이름 붙은 공간이다.","choices":[{"verdict":"오답","why":"boolean 자료형은 true 또는 false를 저장해 조건의 참·거짓을 판단할 때 사용하므로 맞는 설명이다."},{"verdict":"오답","why":"변수는 값을 주기억장치에 기억해 두기 위해 사용하는 공간이므로 맞는 설명이다."},{"verdict":"오답","why":"char 자료형은 한 개의 문자를 저장할 때 사용하므로 맞는 설명이다."},{"verdict":"정답","why":"Java의 실수형 자료형은 float과 double이다. short와 byte는 정수형 자료형이다."}],"keywords":[{"term":"정수형","desc":"byte(1바이트), short(2바이트), int(4바이트), long(8바이트)"},{"term":"실수형","desc":"float(4바이트), double(8바이트)"},{"term":"char","desc":"문자 한 개, Java에서는 2바이트"},{"term":"boolean","desc":"true 또는 false만 저장하는 논리형"}],"memo":"실수형은 소수점이 '떠다니는(float)' 수와 그 두 배 정밀도(double)뿐이다."}},{"id":"written-2025-1-62","no":62,"unit":"프로그래밍 언어 활용","q":"HRN에 관한 설명으로 옳지 않은 것은 다음 중 어느 것인가?","choices":["SJF 기법을 보완하고자 하는 스케쥴링 방법이다.","대기 시간이 긴 프로세스는 우선순위가 높다.","서비스 시간과 대기 시간을 이용하는 방법이다.","우선순위 계산식의 값이 낮을수록 우선순위가 높아진다."],"ans":4,"exp":{"concept":"HRN(Highest Response-ratio Next)은 실행 시간이 짧은 작업만 계속 우대하는 SJF의 단점(긴 작업의 무한 대기)을 보완한 비선점 스케줄링 기법이다. 우선순위 = (대기 시간 + 서비스 시간) ÷ 서비스 시간으로 계산하며, 이 값이 클수록 먼저 실행된다.","choices":[{"verdict":"오답","why":"HRN은 SJF 기법에서 실행 시간이 긴 프로세스가 불리해지는 문제를 보완하기 위한 기법이므로 맞는 설명이다."},{"verdict":"오답","why":"계산식의 분자에 대기 시간이 들어가므로 대기 시간이 길수록 우선순위가 높아진다. 맞는 설명이다."},{"verdict":"오답","why":"우선순위 계산에 서비스 시간과 대기 시간을 모두 사용하므로 맞는 설명이다."},{"verdict":"정답","why":"HRN은 우선순위 계산식의 값이 클수록 우선순위가 높다. 낮을수록 높아진다는 설명은 틀렸다."}],"keywords":[{"term":"HRN","desc":"우선순위 = (대기 시간 + 서비스 시간) ÷ 서비스 시간, 값이 클수록 먼저 실행"},{"term":"SJF","desc":"실행 시간이 가장 짧은 작업을 먼저 실행하는 비선점 기법"},{"term":"에이징(Aging)","desc":"오래 기다린 프로세스의 우선순위를 높여 무한 대기를 막는 기법"}],"memo":"HRN의 H는 Highest, 즉 '가장 높은 응답비'를 먼저 실행한다."}},{"id":"written-2025-1-63","no":63,"unit":"프로그래밍 언어 활용","q":"빈 기억공간의 크기가 20K, 16K, 8K, 40K일 때 기억장치 배치 전략으로 “Worst Fit”을 적용하여 17K의 프로그램을 적재하면 내부 단편화의 크기는 얼마인가? (단, 선택한 기억공간 전체를 할당하며 남는 공간을 별도 블록으로 분할하지 않는다.)","choices":["3K","23K","44K","67K"],"ans":2,"exp":{"concept":"최악 적합(Worst Fit)은 프로그램이 들어갈 수 있는 빈 공간 중 가장 큰 공간에 프로그램을 넣는 배치 전략이다. 할당된 공간에서 프로그램이 쓰고 남은 부분이 내부 단편화가 된다.","choices":[{"verdict":"오답","why":"3K는 17K를 20K 공간에 넣었을 때 남는 크기다. 20K는 최초 적합(First Fit)이나 최적 적합(Best Fit)이 고르는 공간이다."},{"verdict":"정답","why":"17K가 들어갈 수 있는 공간(20K, 40K) 중 가장 큰 40K에 적재하므로 내부 단편화는 40K - 17K = 23K다."},{"verdict":"오답","why":"44K는 사용되지 않은 나머지 빈 공간 20K + 16K + 8K의 합으로, 내부 단편화가 아니다."},{"verdict":"오답","why":"67K는 전체 빈 공간 84K에서 17K를 뺀 값으로, 내부 단편화의 크기가 아니다."}],"keywords":[{"term":"최초 적합(First Fit)","desc":"들어갈 수 있는 첫 번째 빈 공간에 배치"},{"term":"최적 적합(Best Fit)","desc":"들어갈 수 있는 공간 중 단편화가 가장 작은(가장 작은) 공간에 배치"},{"term":"최악 적합(Worst Fit)","desc":"들어갈 수 있는 공간 중 단편화가 가장 큰(가장 큰) 공간에 배치"},{"term":"내부 단편화","desc":"할당된 영역 안에서 사용되지 않고 남는 공간"}],"memo":"Worst는 '가장 많이 남기는' 공간을 고른다. 들어갈 수 없는 16K, 8K는 먼저 제외한다."}},{"id":"written-2025-1-64","no":64,"unit":"프로그래밍 언어 활용","q":"다음 중 IP 버전에 관한 설명으로 옳지 않은 것은?","choices":["IPv4는 네트워크 부분의 길이에 따라 A 클래스부터 E 클래스까지 총 5단계로 구성된다.","IPv6는 각 부분을 콜론으로 구분하여 표기한다.","IPv6는 IPv4와 비교하여 자료 전송 속도가 느리다.","IPv4는 각 부분이 옥텟으로 구성되며, 총 32비트로 이루어진다."],"ans":3,"exp":{"concept":"IPv4는 32비트 주소를 8비트씩 4부분(옥텟)으로 나누어 점(.)으로 구분해 쓰고, A~E 클래스로 나뉜다. IPv6는 128비트 주소를 16비트씩 8부분으로 나누어 콜론(:)으로 구분해 쓴다. IPv6는 주소 공간이 넓고, 헤더가 단순해져 처리 속도가 빨라졌으며, 보안과 품질 보장 기능이 강화되었다.","choices":[{"verdict":"오답","why":"IPv4는 네트워크 부분의 길이에 따라 A, B, C, D, E 다섯 클래스로 구분되므로 맞는 설명이다."},{"verdict":"오답","why":"IPv6는 16비트씩 8부분을 16진수로 표기하고 콜론(:)으로 구분하므로 맞는 설명이다."},{"verdict":"정답","why":"IPv6는 고정 길이의 단순한 기본 헤더를 사용해 IPv4보다 자료 전송 속도가 빠르다. 느리다는 설명이 틀렸다."},{"verdict":"오답","why":"IPv4는 8비트(옥텟)씩 4부분, 총 32비트로 구성되므로 맞는 설명이다."}],"keywords":[{"term":"IPv4","desc":"32비트, 8비트씩 4부분, 점(.)으로 구분, A~E 클래스"},{"term":"IPv6","desc":"128비트, 16비트씩 8부분, 콜론(:)으로 구분"},{"term":"IPv6 주소 체계","desc":"유니캐스트, 멀티캐스트, 애니캐스트(브로드캐스트 없음)"}],"memo":"IPv6는 IPv4를 개선한 버전이므로 '느리다', '보안이 약하다' 같은 보기는 틀린 것이다."}},{"id":"written-2025-1-65","no":65,"unit":"프로그래밍 언어 활용","q":"IPv4와 IPv6 간의 주소 전환에 활용되는 기술에 해당하지 않는 것은?","choices":["라우팅","듀얼 스택","헤더 변환","터널링"],"ans":1,"exp":{"concept":"IPv4에서 IPv6로 넘어가는 과도기에는 두 주소 체계가 함께 쓰이므로 서로 통신하게 해 주는 전환 기술이 필요하다. 대표적인 전환 기술은 듀얼 스택, 터널링, 헤더 변환(주소 변환)이다.","choices":[{"verdict":"정답","why":"라우팅(Routing)은 패킷이 목적지까지 갈 최적 경로를 정하는 기능으로, IPv4와 IPv6 사이의 전환 기술이 아니다."},{"verdict":"오답","why":"듀얼 스택(Dual Stack)은 하나의 장비에 IPv4와 IPv6 프로토콜을 함께 탑재해 둘 다 처리하는 전환 기술이다."},{"verdict":"오답","why":"헤더 변환은 IPv4 헤더와 IPv6 헤더를 서로 변환해 통신하게 하는 전환 기술이다."},{"verdict":"오답","why":"터널링(Tunneling)은 IPv6 패킷을 IPv4 패킷에 담아(캡슐화) IPv4 망을 통과시키는 전환 기술이다."}],"keywords":[{"term":"듀얼 스택","desc":"IPv4와 IPv6를 동시에 지원"},{"term":"터널링","desc":"한 프로토콜의 패킷을 다른 프로토콜 패킷 안에 캡슐화해 전송"},{"term":"헤더 변환","desc":"IPv4와 IPv6 헤더를 서로 변환"},{"term":"라우팅","desc":"목적지까지의 최적 경로 결정"}],"memo":"전환 기술은 '듀얼 스택·터널링·변환' 세 가지다."}},{"id":"written-2025-1-66","no":66,"unit":"프로그래밍 언어 활용","q":"다음 중 C 언어의 산술 연산자에 해당하지 않는 것은?","choices":["/","*","%","&lt;&lt;"],"ans":4,"exp":{"concept":"C 언어의 산술 연산자는 덧셈(+), 뺄셈(-), 곱셈(*), 나눗셈(/), 나머지(%), 증감(++, --)이다. 비트 단위로 자리를 옮기는 <<, >>는 시프트 연산자로 비트 연산자에 속한다.","choices":[{"verdict":"오답","why":"/는 나눗셈을 하는 산술 연산자다."},{"verdict":"오답","why":"*는 곱셈을 하는 산술 연산자다."},{"verdict":"오답","why":"%는 나머지를 구하는 산술 연산자다."},{"verdict":"정답","why":"<<는 비트를 왼쪽으로 이동시키는 시프트(비트) 연산자로, 산술 연산자가 아니다."}],"keywords":[{"term":"산술 연산자","desc":"+, -, *, /, %, ++, --"},{"term":"비트 연산자","desc":"&, |, ^, ~, <<, >>"},{"term":"<<","desc":"비트를 왼쪽으로 이동, 한 칸 이동할 때마다 값이 2배"}],"memo":"<< 는 결과적으로 곱셈처럼 보이지만 분류는 비트(시프트) 연산자다."}},{"id":"written-2025-1-67","no":67,"unit":"프로그래밍 언어 활용","q":"다음 파이썬 코드에 ‘53t44’를 입력하면 출력되는 결과는?<pre class=\"qcode\"><code class=\"language-python\">a, b = map(int, input( ).split( \"t\" ));\nprint(a, b)</code></pre>","choices":["53 t 44","53t44","53 44","53, 44"],"ans":3,"exp":{"concept":"input()은 키보드 입력을 문자열로 받는다. split(\"t\")는 문자열을 't'를 기준으로 잘라 리스트로 만들고, map(int, …)은 각 조각을 정수로 바꾼다. print()에 여러 값을 쉼표로 넘기면 값 사이에 공백 한 칸을 넣어 출력한다.","choices":[{"verdict":"오답","why":"구분자 't'는 split으로 잘려 나가 결과에 남지 않으므로 't'가 출력되지 않는다."},{"verdict":"오답","why":"split(\"t\")가 문자열을 두 조각으로 나누고 각각 정수로 변환하므로 원래 문자열 그대로 출력되지 않는다."},{"verdict":"정답","why":"'53t44'.split(\"t\")는 ['53', '44']가 되고, map(int, …)으로 a=53, b=44가 된다. print(a, b)는 공백으로 구분해 53 44를 출력한다."},{"verdict":"오답","why":"print(a, b)는 기본 구분자(sep)가 공백 한 칸이므로 쉼표가 출력되지 않는다."}],"keywords":[{"term":"split(구분자)","desc":"문자열을 구분자 기준으로 잘라 리스트로 반환"},{"term":"map(함수, 반복 가능 객체)","desc":"각 요소에 함수를 적용"},{"term":"print 기본 구분자","desc":"sep=' ', 여러 값을 공백으로 구분해 출력"}],"memo":"print(a, b)의 쉼표는 '출력할 값의 구분'이지 출력 문자가 아니다."}},{"id":"written-2025-1-68","no":68,"unit":"프로그래밍 언어 활용","q":"다음 결합도(Coupling) 중 가장 약한 것은?","choices":["External Coupling","Stamp Coupling","Content Coupling","Common Coupling"],"ans":2,"exp":{"concept":"결합도는 모듈 간 의존 정도로, 약한 것부터 자료(Data) < 스탬프(Stamp) < 제어(Control) < 외부(External) < 공통(Common) < 내용(Content) 순이다. 보기 중에서 가장 앞에 오는 것을 고르면 된다.","choices":[{"verdict":"오답","why":"외부 결합도(External Coupling)는 어떤 모듈이 선언한 데이터(변수)를 외부의 다른 모듈에서 참조하는 결합으로, 스탬프·제어 결합도보다 강하다."},{"verdict":"정답","why":"스탬프 결합도(Stamp Coupling)는 배열·구조체 같은 자료 구조를 인터페이스로 전달하는 결합으로, 보기 중 가장 약하다."},{"verdict":"오답","why":"내용 결합도(Content Coupling)는 다른 모듈의 내부 기능이나 자료를 직접 참조하는 가장 강한 결합이다."},{"verdict":"오답","why":"공통 결합도(Common Coupling)는 전역 변수를 여러 모듈이 함께 참조하는 결합으로, 외부 결합도보다 강하다."}],"keywords":[{"term":"자료 결합도","desc":"단순 값만 전달, 가장 약함"},{"term":"스탬프 결합도","desc":"자료 구조를 전달"},{"term":"외부 결합도","desc":"외부 모듈이 선언한 데이터를 참조"},{"term":"공통 결합도","desc":"전역 변수 공유"},{"term":"내용 결합도","desc":"다른 모듈 내부를 직접 참조, 가장 강함"}],"memo":"'자스제외공내' 순서에서 앞에 있을수록 약하다."}},{"id":"written-2025-1-69","no":69,"unit":"프로그래밍 언어 활용","q":"HTTP에서 사용하는 잘 알려진(Well Known) 포트 번호는 무엇인가?","choices":["23","80","53","443"],"ans":2,"exp":{"concept":"포트 번호는 한 컴퓨터 안에서 어떤 서비스(프로그램)와 통신할지 구분하는 번호다. 0~1023번은 잘 알려진(Well Known) 포트로, 주요 서비스마다 정해져 있다. HTTP는 80번을 쓴다.","choices":[{"verdict":"오답","why":"23번은 원격 접속 서비스인 Telnet의 포트 번호다."},{"verdict":"정답","why":"80번은 웹 문서를 주고받는 HTTP의 잘 알려진 포트 번호다."},{"verdict":"오답","why":"53번은 도메인 이름을 IP 주소로 바꿔 주는 DNS의 포트 번호다."},{"verdict":"오답","why":"443번은 HTTP에 SSL/TLS 암호화를 더한 HTTPS의 포트 번호다."}],"keywords":[{"term":"FTP","desc":"20(데이터), 21(제어)"},{"term":"SSH·Telnet","desc":"22·23"},{"term":"SMTP·DNS","desc":"25·53"},{"term":"HTTP·HTTPS","desc":"80·443"}],"memo":"HTTP 80과 HTTPS 443을 짝으로 외운다."}},{"id":"written-2025-1-70","no":70,"unit":"프로그래밍 언어 활용","q":"개발 환경 구성에 사용되는 빌드(Build) 도구로 볼 수 없는 것은?","choices":["Maven","Gradle","Kerberos","Ant"],"ans":3,"exp":{"concept":"빌드(Build) 도구는 소스 코드를 컴파일하고 라이브러리 의존성을 해결해 실행 가능한 결과물로 만들어 주는 도구다. Java 계열의 대표적인 빌드 도구로 Ant, Maven, Gradle이 있다.","choices":[{"verdict":"오답","why":"Maven은 Apache의 빌드 도구로, pom.xml로 프로젝트와 라이브러리 의존성을 관리한다."},{"verdict":"오답","why":"Gradle은 Groovy 기반의 빌드 도구로, 안드로이드 앱 개발의 공식 빌드 도구로 쓰인다."},{"verdict":"정답","why":"Kerberos(커버로스)는 티켓을 이용해 사용자를 인증하는 네트워크 인증 프로토콜로, 빌드 도구가 아니다."},{"verdict":"오답","why":"Ant(Another Neat Tool)는 Apache의 Java 빌드 도구로, XML 기반 빌드 스크립트를 사용한다."}],"keywords":[{"term":"Ant","desc":"Apache의 XML 기반 Java 빌드 도구"},{"term":"Maven","desc":"Apache의 빌드 도구, 의존성 관리, pom.xml"},{"term":"Gradle","desc":"Groovy 기반 빌드 도구, 안드로이드 공식 빌드 도구"},{"term":"Kerberos","desc":"티켓 기반 네트워크 인증 프로토콜"}],"memo":"빌드 자동화 도구는 'Ant·Maven·Gradle·Jenkins'로 묶어 외우고, Kerberos는 보안(인증) 쪽으로 분류한다."}},{"id":"written-2025-1-71","no":71,"unit":"프로그래밍 언어 활용","q":"다음 C 언어 프로그램을 실행한 결과로 옳은 것은?<pre class=\"qcode\"><code class=\"language-c\">#include &lt;stdio.h&gt;\nmain() {\n    int i = 0;\n    while (1) {\n        if (i == 4)\n            break;\n        i++;\n    }\n    printf(\"%d\", i);\n}</code></pre>","choices":["3","4","5","6"],"ans":2,"exp":{"concept":"while(1)은 조건이 항상 참이라 무한히 반복하지만, 안에서 break를 만나면 즉시 반복을 빠져나온다. 이 코드는 i를 1씩 늘리다가 i가 4가 되는 순간 break로 빠져나온다.","choices":[{"verdict":"오답","why":"i가 3일 때는 i == 4가 거짓이라 break 없이 i++로 4가 된다. 3에서 멈추지 않는다."},{"verdict":"정답","why":"i = 0, 1, 2, 3일 때는 i++로 1씩 늘어나고, i가 4가 된 다음 반복에서 if (i == 4)가 참이 되어 break한다. 반복을 빠져나온 뒤 printf가 4를 출력한다."},{"verdict":"오답","why":"i가 4일 때 i++보다 먼저 if 검사에서 break하므로 5까지 증가하지 않는다."},{"verdict":"오답","why":"i는 4에서 반복을 빠져나오므로 6이 될 수 없다."}],"keywords":[{"term":"while(1)","desc":"조건이 항상 참인 무한 반복"},{"term":"break","desc":"가장 가까운 반복문을 즉시 빠져나옴"},{"term":"i++","desc":"i 값을 1 증가"}],"memo":"break 검사가 증가(i++)보다 앞에 있는지 뒤에 있는지에 따라 결과가 1 달라진다. 순서를 꼭 확인한다."}},{"id":"written-2025-1-72","no":72,"unit":"프로그래밍 언어 활용","q":"정수를 입력받아 처리하는 아래 C 언어 프로그램의 괄호 안에 들어갈 알맞은 코드는?<pre class=\"qcode\"><code class=\"language-c\">#include &lt;stdio.h&gt;\nint main(void) {\n    int n, sum = 3;\n    (          )\n    sum = sum + n;\n    printf(\"%d\", sum);\n}</code></pre>","choices":["scanf(\"%f\", &amp;n);","scanf(\"%d\", n);","scanf(\"%f\", n);","scanf(\"%d\", &amp;n);"],"ans":4,"exp":{"concept":"scanf는 입력받은 값을 변수에 저장하므로, 변수의 값이 아니라 변수의 주소를 넘겨야 한다. 그래서 일반 변수 앞에는 주소 연산자 &를 붙인다. 또 서식 문자는 변수의 자료형과 맞아야 하는데, int에는 %d, float에는 %f를 쓴다.","choices":[{"verdict":"오답","why":"%f는 실수(float)용 서식 문자인데 n은 int형이므로 자료형이 맞지 않는다."},{"verdict":"오답","why":"서식 문자 %d는 맞지만 &가 없어 n의 주소가 아닌 값(쓰레기값)을 넘기게 되므로 올바르지 않다."},{"verdict":"오답","why":"%f는 int형 n에 맞지 않고, &도 빠져 있어 두 가지 모두 틀렸다."},{"verdict":"정답","why":"int형 n에 맞는 %d와 주소 연산자 &를 함께 쓴 scanf(\"%d\", &n);이 올바르다. 예를 들어 5를 입력하면 sum = 3 + 5가 되어 8이 출력된다."}],"keywords":[{"term":"scanf","desc":"표준 입력에서 서식에 맞춰 값을 읽어 변수에 저장하는 함수"},{"term":"&(주소 연산자)","desc":"변수의 메모리 주소를 구함"},{"term":"%d / %f","desc":"정수(int) / 실수(float) 서식 문자"}],"memo":"scanf는 '%d와 &' 두 가지를 동시에 확인한다. 배열 이름이나 문자열(%s)은 그 자체가 주소라 &를 붙이지 않는다."}},{"id":"written-2025-1-73","no":73,"unit":"프로그래밍 언어 활용","q":"다음 JAVA 프로그램을 실행했을 때 출력되는 결과는?<pre class=\"qcode\"><code class=\"language-java\">public class ovr {\n    public static void main(String[ ] args) {\n        int a = 1, b = 2, c = 3, d = 4;\n        int mx, mn;\n        mx = a &lt; b ? b : a;\n        if (mx == 1) {\n            mn = a &gt; mx ? b : a;\n        }\n        else {\n            mn = b &lt; mx ? d : c;\n        }\n        System.out.println(mn);\n    }\n}</code></pre>","choices":["1","2","3","4"],"ans":3,"exp":{"concept":"삼항 연산자 '조건 ? 값1 : 값2'는 조건이 참이면 값1, 거짓이면 값2를 고른다. 이 코드는 먼저 a, b 중 큰 값을 mx에 넣고, mx 값에 따라 if 또는 else 블록에서 mn을 정한다.","choices":[{"verdict":"오답","why":"1이 나오려면 if 블록이 실행되어야 하지만, mx는 2이므로 mx == 1이 거짓이라 if 블록은 실행되지 않는다."},{"verdict":"오답","why":"2는 mx의 값일 뿐 mn에 들어가는 값이 아니다."},{"verdict":"정답","why":"mx = a < b ? b : a에서 1 < 2가 참이므로 mx = 2다. mx == 1이 거짓이므로 else로 가서 mn = b < mx ? d : c를 계산하는데, 2 < 2가 거짓이므로 mn = c = 3이 되어 3이 출력된다."},{"verdict":"오답","why":"4가 되려면 b < mx가 참이어야 하지만 b와 mx가 모두 2라서 2 < 2는 거짓이다."}],"keywords":[{"term":"삼항 연산자","desc":"조건 ? 참일 때 값 : 거짓일 때 값"},{"term":"비교 연산자 <","desc":"같은 값이면 거짓"},{"term":"if-else","desc":"조건에 따라 두 블록 중 하나만 실행"}],"memo":"b < mx에서 b와 mx가 같을 때 '<'는 거짓이다. 같은 값 비교에서 실수가 잦다."}},{"id":"written-2025-1-74","no":74,"unit":"프로그래밍 언어 활용","q":"네트워크 장비에 관한 설명 중 옳지 않은 것은?","choices":["브리지는 LAN과 LAN을 연결하거나 LAN 내부의 컴퓨터 그룹을 연결하는 기능을 수행하며, 데이터 링크 계층 중 MAC 계층에서 사용된다.","라우터는 LAN과 LAN의 연결 기능에 데이터 전송의 최적 경로를 선택하는 기능이 추가된 것으로, 서로 다른 LAN이나 LAN과 WAN의 연결도 수행하며, OSI 7계층의 네트워크 계층에서 동작한다.","브라우터는 전송되는 신호가 전송 선로의 특성이나 외부 충격 등의 요인 때문에 원래 형태와 다르게 왜곡되거나 약해질 경우 원래의 신호 형태로 재생하여 다시 전송하는 역할을 한다.","스위치는 LAN과 LAN을 연결하여 훨씬 더 큰 LAN을 구성하는 장치로서, OSI 7계층의 2계층에서 사용된다."],"ans":3,"exp":{"concept":"네트워크 장비는 동작하는 OSI 계층에 따라 구분된다. 리피터·허브는 1계층(물리), 브리지·스위치는 2계층(데이터 링크), 라우터는 3계층(네트워크), 게이트웨이는 그 이상 계층에서 동작한다. 브라우터(Brouter)는 브리지(Bridge)와 라우터(Router)의 기능을 합친 장비다.","choices":[{"verdict":"오답","why":"브리지는 LAN과 LAN, 또는 LAN 안의 컴퓨터 그룹을 연결하며 데이터 링크 계층의 MAC 계층에서 동작하므로 맞는 설명이다."},{"verdict":"오답","why":"라우터는 LAN 연결 기능에 최적 경로 선택 기능을 더한 장비로, 서로 다른 LAN이나 LAN과 WAN을 연결하며 네트워크 계층에서 동작하므로 맞는 설명이다."},{"verdict":"정답","why":"왜곡되거나 약해진 신호를 원래 형태로 재생해 다시 전송하는 것은 리피터(Repeater)의 역할이다. 브라우터는 브리지와 라우터의 기능을 함께 갖춘 장비다."},{"verdict":"오답","why":"스위치는 LAN과 LAN을 연결해 더 큰 LAN을 만드는 장치로 OSI 2계층에서 사용되므로 맞는 설명이다."}],"keywords":[{"term":"리피터","desc":"약해진 신호를 증폭·재생, 1계층"},{"term":"브리지·스위치","desc":"LAN 간 연결, MAC 주소 기반, 2계층"},{"term":"라우터","desc":"최적 경로 선택, IP 주소 기반, 3계층"},{"term":"브라우터","desc":"브리지와 라우터 기능을 결합한 장비"}],"memo":"신호를 '재생·증폭'하면 리피터다. 이름(Brouter)에 Bridge와 Router가 들어 있는 것을 떠올리자."}},{"id":"written-2025-1-75","no":75,"unit":"프로그래밍 언어 활용","q":"순차 파일에 관한 설명 중 옳지 않은 것은?","choices":["필요한 레코드를 삽입, 삭제, 수정할 때 파일을 재구성할 필요가 없으므로 파일 전체를 복사하지 않아도 된다.","레코드가 연속적으로 저장되어 레코드 사이에 빈 공간이 존재하지 않으므로 기억 장치를 효율적으로 이용할 수 있다.","매체 변환이 쉬워서 어떠한 매체에도 적용이 가능하다.","레코드들이 순차적으로 처리되기 때문에 대화식 처리보다는 일괄 처리에 적합하다."],"ans":1,"exp":{"concept":"순차 파일(Sequential File)은 레코드를 들어온 순서대로 또는 키 순서대로 연속해서 저장하는 파일이다. 빈 공간 없이 촘촘히 저장되므로 공간 효율이 좋고 일괄 처리에 적합하지만, 중간에 레코드를 넣거나 빼려면 파일 전체를 다시 써야 한다.","choices":[{"verdict":"정답","why":"순차 파일은 레코드를 삽입·삭제·수정할 때 파일을 재구성해야 하므로 파일 전체를 복사해야 한다. 재구성이 필요 없다는 설명이 틀렸다."},{"verdict":"오답","why":"레코드를 연속으로 저장해 레코드 사이에 빈 공간이 없으므로 기억 장치를 효율적으로 쓸 수 있다. 맞는 설명이다."},{"verdict":"오답","why":"순차 파일은 매체 변환이 쉬워 어떤 매체에도 적용할 수 있으므로 맞는 설명이다."},{"verdict":"오답","why":"레코드를 순서대로 처리하므로 대화식 처리보다 일괄 처리에 적합하다. 맞는 설명이다."}],"keywords":[{"term":"순차 파일","desc":"레코드를 순서대로 연속 저장, 일괄 처리에 적합"},{"term":"직접 파일","desc":"해싱 등으로 계산한 주소에 레코드를 저장, 임의 접근이 빠름"},{"term":"색인 순차 파일","desc":"순차 처리와 색인을 이용한 직접 처리를 모두 지원"}],"memo":"순차 파일의 단점은 '중간 삽입·삭제가 어렵고 검색이 느리다'이다."}},{"id":"written-2025-1-76","no":76,"unit":"프로그래밍 언어 활용","q":"배치 프로그램의 필수 요소에 관한 설명 중 틀린 것은?","choices":["자동화는 심각한 오류 상황을 제외하고는 사용자의 개입 없이 동작해야 한다.","대용량 데이터는 대용량의 데이터를 처리할 수 있어야 한다.","안정성은 어떤 문제가 생겼는지, 언제 발생했는지 등을 추적할 수 있어야 한다.","무결성은 주어진 시간 내에 처리를 완료할 수 있어야 하며, 동시에 동작 중인 다른 애플리케이션을 방해하지 말아야 한다."],"ans":4,"exp":{"concept":"배치 프로그램(Batch Program)은 사용자와의 상호작용 없이 정해진 시간에 대량의 데이터를 일괄로 처리하는 프로그램이다. 필수 요소는 대용량 데이터, 자동화, 견고성, 안정성(신뢰성), 성능 다섯 가지다.","choices":[{"verdict":"오답","why":"자동화는 심각한 오류 상황을 제외하고는 사용자의 개입 없이 동작해야 한다는 요소이므로 맞는 설명이다."},{"verdict":"오답","why":"대용량 데이터는 대량의 데이터를 가져오고, 전달하고, 계산하는 등의 처리를 할 수 있어야 한다는 요소이므로 맞는 설명이다."},{"verdict":"오답","why":"안정성(신뢰성)은 어떤 문제가 생겼는지, 언제 발생했는지 등을 추적할 수 있어야 한다는 요소이므로 맞는 설명이다."},{"verdict":"정답","why":"주어진 시간 내에 처리를 완료하고 동시에 동작하는 다른 애플리케이션을 방해하지 않아야 한다는 것은 '성능'에 대한 설명이다. 무결성은 배치 프로그램의 필수 요소로 꼽히지 않는다."}],"keywords":[{"term":"대용량 데이터","desc":"대량의 데이터를 처리할 수 있어야 함"},{"term":"자동화","desc":"심각한 오류 외에는 사용자 개입 없이 동작"},{"term":"견고성","desc":"잘못된 데이터나 중복 데이터가 있어도 비정상 중단 없이 처리"},{"term":"안정성(신뢰성)","desc":"문제의 내용과 발생 시점을 추적할 수 있어야 함"},{"term":"성능","desc":"주어진 시간 내 처리 완료, 다른 애플리케이션을 방해하지 않음"}],"memo":"배치 필수 요소는 '대·자·견·안·성'이다. 이름과 설명이 엇갈려 짝지어진 보기를 찾는다."}},{"id":"written-2025-1-77","no":77,"unit":"프로그래밍 언어 활용","q":"임계 구역에 대한 접근을 다음과 같은 형태로 제어하는 상호배제 기법은?<pre class=\"qcode\"><code>P(S) : while S &lt; = 0 do skip;\nS := S - 1;\nV(S) : S := S + 1;</code></pre>","choices":["Peterson Algorithm","Dekker Algorithm","Lamport Algorithm","Semaphore"],"ans":4,"exp":{"concept":"세마포어(Semaphore)는 다익스트라(Dijkstra)가 제안한 상호 배제 기법으로, 정수 변수 S와 두 연산 P, V로 임계 구역 진입을 제어한다. P(S)는 S가 0 이하이면 기다렸다가 S를 1 줄이고 들어가며, V(S)는 나올 때 S를 1 늘려 다른 프로세스가 들어갈 수 있게 한다. 화장실 열쇠 개수를 S로 생각하면 쉽다.","choices":[{"verdict":"오답","why":"피터슨 알고리즘(Peterson Algorithm)은 두 프로세스가 공유 변수(flag, turn)만으로 상호 배제를 구현하는 소프트웨어 기법으로, P·V 연산을 쓰지 않는다."},{"verdict":"오답","why":"데커 알고리즘(Dekker Algorithm)은 두 프로세스 간 상호 배제를 공유 변수로 구현한 최초의 소프트웨어 기법으로, P·V 연산을 쓰지 않는다."},{"verdict":"오답","why":"램포트 알고리즘(Lamport Algorithm, 빵집 알고리즘)은 번호표를 받아 순서대로 임계 구역에 들어가는 n개 프로세스용 상호 배제 기법으로, P·V 연산을 쓰지 않는다."},{"verdict":"정답","why":"P(S)에서 S가 0 이하이면 대기하다가 S를 감소시키고, V(S)에서 S를 증가시키는 구조는 세마포어의 P·V 연산이다."}],"keywords":[{"term":"세마포어","desc":"P·V 연산으로 상호 배제를 구현하는 기법, 다익스트라 제안"},{"term":"P 연산","desc":"Wait, S를 감소시키며 진입, S ≤ 0이면 대기"},{"term":"V 연산","desc":"Signal, S를 증가시켜 대기 중인 프로세스를 깨움"},{"term":"임계 구역","desc":"한 번에 하나의 프로세스만 접근해야 하는 공유 자원 영역"}],"memo":"P와 V가 보이면 세마포어다. P는 들어갈 때(감소), V는 나올 때(증가)다."}},{"id":"written-2025-1-78","no":78,"unit":"프로그래밍 언어 활용","q":"C 언어에서 변수 이름으로 사용할 수 없는 것은?","choices":["_sub","short","int01","data02"],"ans":2,"exp":{"concept":"C 언어의 변수 이름은 영문자, 숫자, 밑줄(_)로 만들며 숫자로 시작할 수 없다. 또한 int, short, return처럼 언어가 미리 쓰임새를 정해 둔 예약어(키워드)는 변수 이름으로 쓸 수 없다.","choices":[{"verdict":"오답","why":"_sub는 밑줄로 시작하는데, 밑줄은 첫 글자로 쓸 수 있으므로 변수 이름으로 사용 가능하다."},{"verdict":"정답","why":"short는 정수 자료형을 나타내는 C 언어 예약어이므로 변수 이름으로 쓸 수 없다."},{"verdict":"오답","why":"int01은 예약어 int에 숫자를 붙인 별개의 이름이고 영문자로 시작하므로 변수 이름으로 사용 가능하다."},{"verdict":"오답","why":"data02는 영문자로 시작하고 영문자·숫자로만 이루어져 변수 이름으로 사용 가능하다."}],"keywords":[{"term":"식별자 규칙","desc":"영문자·숫자·밑줄 사용, 숫자로 시작 불가, 공백 불가, 대소문자 구분"},{"term":"예약어","desc":"int, short, long, char, if, while, return 등 미리 정해진 단어"},{"term":"대소문자 구분","desc":"C 언어는 Data와 data를 서로 다른 이름으로 본다"}],"memo":"예약어를 '포함'한 이름(int01)은 쓸 수 있고, 예약어 '그 자체'(short)는 쓸 수 없다."}},{"id":"written-2025-1-79","no":79,"unit":"프로그래밍 언어 활용","q":"다음은 n각형을 화면에 그리는 프로그램을 Python으로 작성한 것이다. 괄호(㉠~㉢)에 들어갈 코드로 알맞은 것은?<pre class=\"qcode\"><code class=\"language-python\">import turtle\n( ㉠ ) shape(distance, n):\n    t = turtle.Turtle( )\n    for i in range(n):\n        t.( ㉡ )\n        t.( ㉢ )\nshape(100, 5)</code></pre>","choices":["class, forward(distance), left(360///n)","def, forward(distance), left(360///n)","class, forward(distance), left(360//n)","def, forward(distance), left(360//n)"],"ans":4,"exp":{"concept":"파이썬에서 함수를 정의할 때는 def 키워드를 쓴다(class는 클래스를 정의할 때 쓴다). 정다각형을 그리려면 한 변을 그린 뒤 360 ÷ n도만큼 회전하는 동작을 n번 반복하면 된다. 파이썬의 정수 나눗셈 연산자는 // 이고, ///라는 연산자는 없다.","choices":[{"verdict":"오답","why":"shape(distance, n)처럼 매개변수를 받는 함수 정의에는 class가 아니라 def를 써야 하고, 360///n도 문법 오류다."},{"verdict":"오답","why":"def는 맞지만 ///는 파이썬에 없는 연산자라 문법 오류(SyntaxError)가 난다."},{"verdict":"오답","why":"360//n은 맞지만 함수 정의에 class를 쓴 것이 틀렸다."},{"verdict":"정답","why":"def로 함수를 정의하고, forward(distance)로 한 변을 그린 뒤 left(360//n)로 회전한다. shape(100, 5)에서는 길이 100을 그리고 72도씩 도는 동작을 5번 반복해 오각형이 그려진다."}],"keywords":[{"term":"def","desc":"파이썬에서 함수를 정의하는 키워드"},{"term":"class","desc":"파이썬에서 클래스를 정의하는 키워드"},{"term":"//","desc":"몫만 구하는 정수 나눗셈 연산자, 360//5 = 72"},{"term":"range(n)","desc":"0부터 n-1까지 n번 반복"}],"memo":"파이썬 나눗셈은 /(실수 결과), //(몫) 두 가지뿐이고, 함수는 항상 def로 시작한다."}},{"id":"written-2025-1-80","no":80,"unit":"프로그래밍 언어 활용","q":"프로세스에 관한 설명 중 틀린 것은?","choices":["준비 상태의 프로세스에 프로세서가 배당되어 실행 상태로 바뀌는 것을 디스패치(Dispatch)라고 한다.","이전 프로세스의 상태 레지스터 내용을 보관한 뒤 다른 프로세스의 레지스터를 적재하는 과정을 문맥 교환(Context Switching)이라고 한다.","프로세스는 스레드(Thread) 내에서 실행되는 흐름의 단위로, 스레드와 달리 주소 공간에 실행 스택(Stack)이 없다.","프로세스 제어 블록(PCB, Process Control Block)은 프로세스 식별자, 프로세스 상태 등의 정보로 이루어진다."],"ans":3,"exp":{"concept":"프로세스(Process)는 실행 중인 프로그램으로, 자기만의 주소 공간(코드, 데이터, 스택 등)을 가진다. 스레드(Thread)는 프로세스 안에서 실행되는 흐름의 단위로, 같은 프로세스의 자원을 공유하면서도 각자 자기 스택을 가진다. 즉 프로세스가 스레드를 품는 관계이지 그 반대가 아니다.","choices":[{"verdict":"오답","why":"준비 상태의 프로세스가 CPU를 할당받아 실행 상태로 바뀌는 것을 디스패치(Dispatch)라고 하므로 맞는 설명이다."},{"verdict":"오답","why":"실행 중이던 프로세스의 레지스터 등 상태를 보관하고 다음 프로세스의 상태를 적재하는 과정을 문맥 교환(Context Switching)이라고 하므로 맞는 설명이다."},{"verdict":"정답","why":"스레드가 프로세스 안에서 실행되는 흐름의 단위다. 이 보기는 프로세스와 스레드를 거꾸로 설명했고, 프로세스는 자기 주소 공간에 실행 스택을 가진다."},{"verdict":"오답","why":"PCB(Process Control Block)에는 프로세스 식별자, 프로세스 상태, 프로그램 카운터, 레지스터 정보 등이 저장되므로 맞는 설명이다."}],"keywords":[{"term":"프로세스","desc":"실행 중인 프로그램, 독립된 주소 공간을 가짐"},{"term":"스레드","desc":"프로세스 내 실행 흐름의 단위, 자원을 공유하고 스택은 각자 가짐"},{"term":"디스패치","desc":"준비 상태 → 실행 상태 전이"},{"term":"문맥 교환","desc":"CPU를 다른 프로세스에 넘길 때 상태를 저장·복원하는 과정"},{"term":"PCB","desc":"운영체제가 프로세스 정보를 저장하는 블록"}],"memo":"'프로세스 안에 스레드'가 들어 있다. 포함 관계가 뒤바뀐 보기를 조심한다."}},{"id":"written-2025-1-81","no":81,"unit":"정보시스템 구축 관리","q":"다음 중 Secure OS의 보안 기능과 거리가 먼 것은?","choices":["고가용성 지원","임의적 접근 통제","식별 및 인증","강제적 접근 통제"],"ans":1,"exp":{"concept":"Secure OS(보안 운영체제)는 운영체제 커널에 보안 기능을 넣어 해킹으로부터 시스템을 보호하는 운영체제다. 주요 보안 기능은 식별 및 인증, 임의적 접근 통제, 강제적 접근 통제, 객체 재사용 보호, 완전한 조정, 신뢰 경로, 감사 및 감사 기록 축소 등이다.","choices":[{"verdict":"정답","why":"고가용성(High Availability)은 장애가 나도 서비스가 계속되도록 하는 시스템 구성 방식으로, Secure OS의 보안 기능이 아니다."},{"verdict":"오답","why":"임의적 접근 통제(DAC)는 사용자나 그룹의 신분에 따라 소유자가 접근 권한을 정하는 Secure OS의 보안 기능이다."},{"verdict":"오답","why":"식별 및 인증은 사용자가 누구인지 확인하는 Secure OS의 기본 보안 기능이다."},{"verdict":"오답","why":"강제적 접근 통제(MAC)는 주체와 객체의 보안 등급에 따라 접근을 제어하는 Secure OS의 보안 기능이다."}],"keywords":[{"term":"Secure OS","desc":"커널에 보안 기능을 추가한 운영체제"},{"term":"임의적 접근 통제(DAC)","desc":"소유자가 신분 기반으로 접근 권한 부여"},{"term":"강제적 접근 통제(MAC)","desc":"보안 등급(레이블) 기반으로 시스템이 접근 통제"},{"term":"객체 재사용 보호","desc":"사용이 끝난 메모리·디스크 공간을 재할당 전에 초기화"}],"memo":"Secure OS 기능은 '인증·접근 통제·감사' 같은 보안 기능이다. 가용성 확보는 이중화 같은 시스템 구성 기술이다."}},{"id":"written-2025-1-82","no":82,"unit":"정보시스템 구축 관리","q":"다음 중 프로토타입 모형을 선택하기에 가장 적합한 경우는 어느 것인가?","choices":["고객이 개발 과정에 참여하지 않는 경우","고객이 완성된 제품만을 보고자 하는 경우","구축하려는 시스템의 요구사항이 불분명한 경우","소프트웨어 개발 과정에서 발생할 수 있는 위험을 최소화하려는 경우"],"ans":3,"exp":{"concept":"프로토타입 모형은 견본을 만들어 고객에게 보여 주며 요구사항을 구체화하는 모형이다. 고객이 무엇을 원하는지 처음에 분명하지 않을 때 가장 효과적이다.","choices":[{"verdict":"오답","why":"고객이 개발 과정에 참여하지 않으면 프로토타입에 대한 피드백을 받을 수 없으므로 프로토타입 모형에 적합하지 않다."},{"verdict":"오답","why":"고객이 완성된 제품만 보려 한다면 중간 시제품으로 의견을 받는 프로토타입 모형의 장점을 살릴 수 없다."},{"verdict":"정답","why":"요구사항이 불분명할 때 시제품을 보여 주며 요구사항을 끌어내고 확정할 수 있으므로 프로토타입 모형이 가장 적합하다."},{"verdict":"오답","why":"개발 과정에서 발생할 수 있는 위험을 최소화하는 데 초점을 둔 것은 위험 분석 단계를 반복하는 나선형 모형(Spiral Model)이다."}],"keywords":[{"term":"프로토타입 모형","desc":"시제품으로 요구사항을 구체화, 요구사항이 불분명할 때 적합"},{"term":"나선형 모형","desc":"계획 수립 → 위험 분석 → 개발 → 고객 평가를 반복, 위험 관리 중시"},{"term":"폭포수 모형","desc":"단계를 순차적으로 진행, 요구사항이 명확할 때 적합"}],"memo":"'요구사항 불분명'이면 프로토타입, '위험 최소화'면 나선형이다."}},{"id":"written-2025-1-83","no":83,"unit":"정보시스템 구축 관리","q":"다음 설명에 해당하는 것은?<div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul><li>사물통신, 사물인터넷처럼 대역폭이 제한된 통신환경에 최적화되어 개발된 푸시기술 기반의 경량 메시지 전송 프로토콜</li><li>메시지 매개자(Broker)를 거쳐 송신자가 특정 메시지를 발행하고 수신자가 그 메시지를 구독하는 방식</li><li>IBM 주도로 개발됨</li></ul></div>","choices":["GRID","MQTT","TELNET","GPN"],"ans":2,"exp":{"concept":"MQTT(Message Queuing Telemetry Transport)는 IBM이 주도해 만든 사물인터넷(IoT)용 경량 메시지 프로토콜이다. 발행(Publish)/구독(Subscribe) 방식으로, 송신자가 브로커(Broker)에 메시지를 발행하면 그 주제를 구독한 수신자들이 메시지를 받는다. 대역폭이 좁고 전력이 부족한 환경에 적합하다.","choices":[{"verdict":"오답","why":"그리드(GRID)는 지리적으로 흩어진 컴퓨팅 자원을 네트워크로 묶어 하나의 큰 컴퓨터처럼 쓰는 그리드 컴퓨팅 기술로, 메시지 프로토콜이 아니다."},{"verdict":"정답","why":"MQTT는 IBM이 주도해 개발한 발행/구독 기반의 경량 메시지 전송 프로토콜로, 대역폭이 제한된 사물통신·사물인터넷 환경에 최적화되어 있다."},{"verdict":"오답","why":"TELNET은 원격지 컴퓨터에 접속해 명령을 실행하는 원격 접속 프로토콜(TCP 23번 포트)이다."},{"verdict":"오답","why":"GPN은 이 설명에 해당하는 출제 범위의 표준 용어가 아니다."}],"keywords":[{"term":"MQTT","desc":"IoT용 발행/구독 기반 경량 메시지 프로토콜, IBM 주도"},{"term":"브로커(Broker)","desc":"발행된 메시지를 받아 구독자에게 전달하는 중개자"},{"term":"발행/구독(Pub/Sub)","desc":"송신자는 주제에 발행하고 수신자는 주제를 구독하는 통신 방식"}],"memo":"'IoT + 경량 + 발행/구독 + 브로커 + IBM'이 나오면 MQTT다."}},{"id":"written-2025-1-84","no":84,"unit":"정보시스템 구축 관리","q":"취약점 관리를 위한 응용 프로그램의 보안 설정과 가장 거리가 먼 것은?","choices":["운영체제의 정보 수집 제한","운영체제의 접근 제한","서버 관리실 출입 통제","실행 프로세스 권한 설정"],"ans":3,"exp":{"concept":"응용 프로그램과 운영체제의 보안 설정은 소프트웨어 안에서 취약점을 줄이는 설정이다. 운영체제의 접근 제한, 정보 수집 제한, 실행 프로세스 권한 설정, 불필요한 서비스 차단 등이 해당한다. 출입 통제처럼 건물·장소를 지키는 것은 물리적 보안에 속한다.","choices":[{"verdict":"오답","why":"운영체제의 정보 수집 제한은 공격자가 시스템 정보를 얻지 못하도록 하는 소프트웨어 보안 설정이다."},{"verdict":"오답","why":"운영체제의 접근 제한은 허가되지 않은 사용자의 접근을 막는 소프트웨어 보안 설정이다."},{"verdict":"정답","why":"서버 관리실 출입 통제는 사람의 물리적 출입을 막는 물리적 보안 대책으로, 응용 프로그램의 보안 설정과 거리가 멀다."},{"verdict":"오답","why":"실행 프로세스 권한 설정은 프로세스가 필요한 최소 권한으로만 실행되도록 하는 소프트웨어 보안 설정이다."}],"keywords":[{"term":"물리적 보안","desc":"출입 통제, CCTV, 잠금장치 등 장소·장비를 지키는 보안"},{"term":"최소 권한 원칙","desc":"프로세스나 사용자에게 꼭 필요한 권한만 부여"},{"term":"정보 수집 제한","desc":"시스템 버전·구성 정보 노출을 막는 설정"}],"memo":"보기 중 혼자 '사람이 드나드는 공간' 이야기를 하는 것이 정답이다."}},{"id":"written-2025-1-85","no":85,"unit":"정보시스템 구축 관리","q":"입력 데이터 검증 및 표현에 관한 설명 중 옳지 않은 것은?","choices":["운영체제 명령어 삽입 : 외부 입력값을 통해 시스템 명령어의 실행을 유도하여 권한을 탈취하거나 시스템 장애를 일으킨다.","SQL 삽입 : 웹 응용 프로그램에 SQL을 삽입해 내부 데이터베이스(DB) 서버의 데이터를 유출·변조하고, 관리자 인증을 우회한다.","자원 삽입 : 악의적인 명령어가 포함된 스크립트 파일을 업로드하여 시스템에 손상을 준다.","크로스사이트 스크립트 : 웹페이지에 악의적인 스크립트를 삽입해 방문자들의 정보를 탈취한다."],"ans":3,"exp":{"concept":"시큐어 코딩의 '입력 데이터 검증 및 표현'은 외부에서 들어오는 입력값을 검증하지 않아 생기는 보안 약점을 다룬다. SQL 삽입, 운영체제 명령어 삽입, 크로스사이트 스크립트(XSS), 자원 삽입, 위험한 형식 파일 업로드 등이 있다.","choices":[{"verdict":"오답","why":"운영체제 명령어 삽입은 외부 입력값으로 시스템 명령어 실행을 유도해 권한을 탈취하거나 시스템 장애를 일으키는 보안 약점이므로 맞는 설명이다."},{"verdict":"오답","why":"SQL 삽입은 입력란에 SQL을 삽입해 DB 데이터를 유출·변조하거나 관리자 인증을 우회하는 보안 약점이므로 맞는 설명이다."},{"verdict":"정답","why":"악의적인 스크립트 파일을 업로드해 시스템에 손상을 주는 것은 '위험한 형식 파일 업로드'에 대한 설명이다. 자원 삽입은 외부 입력값을 검증 없이 파일 경로·포트 같은 시스템 자원의 식별자로 사용해 자원을 임의로 조작하게 되는 보안 약점이다."},{"verdict":"오답","why":"크로스사이트 스크립트(XSS)는 웹페이지에 악의적인 스크립트를 삽입해 방문자의 정보를 탈취하는 보안 약점이므로 맞는 설명이다."}],"keywords":[{"term":"SQL 삽입","desc":"입력값에 SQL을 넣어 DB 조작"},{"term":"XSS","desc":"웹페이지에 악성 스크립트를 삽입해 방문자 정보 탈취"},{"term":"자원 삽입","desc":"외부 입력값을 시스템 자원 식별자로 사용해 자원을 조작"},{"term":"위험한 형식 파일 업로드","desc":"악성 스크립트 파일을 업로드해 실행·손상 유발"}],"memo":"'업로드'라는 말이 나오면 '위험한 형식 파일 업로드'다. 자원 삽입은 경로·포트 같은 '자원 식별자' 조작이다."}},{"id":"written-2025-1-86","no":86,"unit":"정보시스템 구축 관리","q":"프로젝트에 내재된 위험 요소를 인식하고 그 영향을 분석해 관리하는 활동으로, 프로젝트를 성공시키기 위해 위험 요소를 사전에 예측하고 대비하는 모든 기술과 활동을 포함하는 것은?","choices":["Critical Path Method","Waterfall Model","Risk Analysis","Work Breakdown Structure"],"ans":3,"exp":{"concept":"위험 분석(Risk Analysis)은 프로젝트에 숨어 있는 위험 요소를 미리 찾아내고, 그 영향을 분석해 대비책을 세우는 활동이다. 위험 식별, 위험 분석 및 평가, 위험 관리 계획, 위험 감시 및 조치 순서로 진행된다.","choices":[{"verdict":"오답","why":"CPM(Critical Path Method, 임계 경로 기법)은 작업 순서와 소요 기간을 네트워크로 그려 프로젝트 완료에 걸리는 가장 긴 경로를 찾는 일정 관리 기법이다."},{"verdict":"오답","why":"폭포수 모형(Waterfall Model)은 개발 단계를 순차적으로 진행하는 소프트웨어 생명 주기 모형이다."},{"verdict":"정답","why":"위험 분석(Risk Analysis)은 프로젝트의 위험 요소를 인식하고 영향을 분석해 관리하는, 위험을 사전에 예측·대비하는 모든 기술과 활동이다."},{"verdict":"오답","why":"WBS(Work Breakdown Structure, 작업 분할 구조도)는 프로젝트 목표를 달성하기 위한 작업을 계층적으로 잘게 나눈 구조도다."}],"keywords":[{"term":"위험 분석","desc":"위험 요소를 예측·분석해 대비하는 활동"},{"term":"CPM","desc":"임계 경로를 찾아 일정을 관리하는 기법"},{"term":"WBS","desc":"작업을 계층적으로 분할한 구조도"},{"term":"위험 관리 절차","desc":"위험 식별 → 위험 분석 및 평가 → 위험 관리 계획 → 위험 감시 및 조치"}],"memo":"문제에 '위험'이 여러 번 나오면 답도 Risk가 들어간 보기다."}},{"id":"written-2025-1-87","no":87,"unit":"정보시스템 구축 관리","q":"소수를 활용한 비대칭 암호화 방식의 암호화 알고리즘은?","choices":["SMT","RSA","DES","AES"],"ans":2,"exp":{"concept":"RSA(Rivest Shamir Adleman)는 공개키(비대칭키) 암호화 알고리즘으로, 아주 큰 두 소수를 곱하기는 쉽지만 그 곱을 다시 소인수분해하기는 매우 어렵다는 점을 이용한다. 암호화에 쓰는 키(공개키)와 복호화에 쓰는 키(개인키)가 서로 다르다.","choices":[{"verdict":"오답","why":"SMT는 출제 범위의 암호화 알고리즘이 아니다."},{"verdict":"정답","why":"RSA는 큰 소수의 곱을 소인수분해하기 어렵다는 점에 기반한 대표적인 비대칭(공개키) 암호화 알고리즘이다."},{"verdict":"오답","why":"DES(Data Encryption Standard)는 64비트 블록, 56비트 키를 쓰는 대칭키(개인키) 블록 암호화 알고리즘이다."},{"verdict":"오답","why":"AES(Advanced Encryption Standard)는 DES의 한계를 보완한 대칭키 블록 암호화 알고리즘으로, 128비트 블록에 128·192·256비트 키를 쓴다."}],"keywords":[{"term":"RSA","desc":"소인수분해의 어려움을 이용한 비대칭(공개키) 암호"},{"term":"ECC","desc":"타원 곡선을 이용한 비대칭 암호"},{"term":"DES","desc":"56비트 키의 대칭키 블록 암호"},{"term":"AES","desc":"128·192·256비트 키의 대칭키 블록 암호"}],"memo":"비대칭 암호는 'RSA·ECC·디피-헬만', 대칭 암호는 'DES·AES·SEED·ARIA'로 나누어 외운다."}},{"id":"written-2025-1-88","no":88,"unit":"정보시스템 구축 관리","q":"외부 컴퓨터가 접속해 오면 접속 인가 여부를 점검하여 인가된 경우에는 접속을 허용하고, 그렇지 않은 경우에는 거부할 수 있는 접근제어 유틸리티는?","choices":["trace checker","tcp wrapper","token finder","change detector"],"ans":2,"exp":{"concept":"TCP Wrapper는 외부 컴퓨터가 서버의 서비스에 접속하려 할 때, 미리 정한 접근 제어 목록(허용·거부 목록)과 비교해 접속을 허용할지 거부할지 결정하는 접근 제어 유틸리티다. 건물 입구에서 출입 명단을 확인하는 경비원과 같다.","choices":[{"verdict":"오답","why":"trace checker는 접속 인가 여부를 점검하는 접근 제어 유틸리티로 쓰이는 출제 범위의 표준 용어가 아니다."},{"verdict":"정답","why":"TCP Wrapper는 외부 컴퓨터의 접속 요청을 받아 인가 여부를 점검하고, 인가된 경우 접속을 허용하며 그렇지 않으면 거부하는 접근 제어 유틸리티다."},{"verdict":"오답","why":"token finder는 접근 제어 유틸리티로 쓰이는 출제 범위의 표준 용어가 아니다."},{"verdict":"오답","why":"change detector는 접근 제어 유틸리티로 쓰이는 출제 범위의 표준 용어가 아니다."}],"keywords":[{"term":"TCP Wrapper","desc":"외부 접속의 인가 여부를 점검해 허용·거부하는 접근 제어 유틸리티"},{"term":"접근 제어","desc":"인가된 사용자만 자원에 접근하도록 통제하는 것"},{"term":"hosts.allow·hosts.deny","desc":"TCP Wrapper가 참조하는 허용·거부 목록 파일"}],"memo":"서비스를 '감싸서(wrap)' 접속을 걸러 낸다고 기억한다."}},{"id":"written-2025-1-89","no":89,"unit":"정보시스템 구축 관리","q":"다음 내용이 설명하는 기술로 가장 적절한 것은 무엇인가?<div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul><li>다른 국으로 향하는 호출이 중계를 거치지 않고 직접 접속되는 그물 모양의 네트워크이다.</li><li>통신량이 많은 비교적 소수의 국 사이에 구성될 경우 경제적이고 간편하나, 다수의 국 사이에서는 회선이 세분화 되어 비경제적일수도 있다.</li><li>해당 형태의 무선 네트워크는 대용량을 빠르고 안전하게 전달할 수 있어 행사장이나 군 등에서 널리 활용된다.</li></ul></div>","choices":["Modem Network","Mesh Network","Simple Station Network","Virtual Local Area Network"],"ans":2,"exp":{"concept":"메시 네트워크(Mesh Network)는 각 노드가 그물처럼 서로 직접 연결된 네트워크다. 중계를 거치지 않고 직접 통신하므로 빠르고, 한 경로가 끊겨도 다른 경로로 우회할 수 있어 안정적이다. 그래서 대규모 인원이 모이는 행사장이나 군사 작전처럼 기존 통신망을 쓰기 어려운 곳에서 활용된다.","choices":[{"verdict":"오답","why":"Modem Network는 이 설명에 해당하는 출제 범위의 표준 용어가 아니다. 모뎀(Modem)은 디지털 신호와 아날로그 신호를 서로 변환하는 장치다."},{"verdict":"정답","why":"메시 네트워크는 그물 모양으로 노드가 직접 연결되는 네트워크로, 대용량 데이터를 빠르고 안전하게 전달할 수 있어 행사장, 군 등에서 활용된다."},{"verdict":"오답","why":"Simple Station Network는 이 설명에 해당하는 출제 범위의 표준 용어가 아니다."},{"verdict":"오답","why":"VLAN(Virtual Local Area Network)은 물리적 배치와 관계없이 논리적으로 LAN을 나누어 구성하는 기술이다."}],"keywords":[{"term":"메시 네트워크","desc":"노드들이 그물처럼 직접 연결된 네트워크, 무선 메시는 행사장·군 등에서 활용"},{"term":"망형(Mesh) 토폴로지","desc":"모든 노드가 서로 연결된 구조, n개 노드일 때 회선 수 n(n-1)/2"},{"term":"VLAN","desc":"논리적으로 분할한 가상 LAN"}],"memo":"'그물 모양'은 영어로 Mesh다."}},{"id":"written-2025-1-90","no":90,"unit":"정보시스템 구축 관리","q":"인증 유형 가운데 패스워드를 이용하는 경우에 해당하는 인증 유형은?","choices":["Something You Are","Somewhere You Are","Something You Have","Something You Know"],"ans":4,"exp":{"concept":"사용자 인증 방식은 무엇으로 신원을 증명하느냐에 따라 나뉜다. 알고 있는 것(Something You Know: 비밀번호, PIN), 가지고 있는 것(Something You Have: 스마트카드, OTP 토큰), 자신의 신체(Something You Are: 지문, 홍채), 있는 위치(Somewhere You Are: GPS, IP 주소)가 있다.","choices":[{"verdict":"오답","why":"Something You Are는 지문, 홍채, 얼굴 같은 사용자의 생체 정보를 이용하는 인증이다."},{"verdict":"오답","why":"Somewhere You Are는 사용자가 있는 위치(GPS, IP 주소, 콜백)를 이용하는 인증이다."},{"verdict":"오답","why":"Something You Have는 스마트카드, OTP 토큰, 출입 카드처럼 사용자가 소지한 것을 이용하는 인증이다."},{"verdict":"정답","why":"패스워드는 사용자가 기억하고 있는 정보이므로 지식 기반 인증인 Something You Know에 해당한다."}],"keywords":[{"term":"지식 기반(Know)","desc":"패스워드, PIN"},{"term":"소유 기반(Have)","desc":"스마트카드, OTP, 신분증"},{"term":"생체 기반(Are)","desc":"지문, 홍채, 얼굴, 정맥"},{"term":"위치 기반(Where)","desc":"GPS, IP 주소, 콜백"}],"memo":"비밀번호는 머리로 '아는' 것이다. Know = 지식이다."}},{"id":"written-2025-1-91","no":91,"unit":"정보시스템 구축 관리","q":"다음 설명에 해당하는 용어로 옳은 것은?<div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul><li>오픈 소스 기반의 분산 컴퓨팅 플랫폼이다.</li><li>일반 PC급 컴퓨터들을 이용해 가상화된 대형 스토리지를 형성한다.</li><li>다양한 소스에서 생성된 빅데이터를 효율적으로 저장·처리한다.</li></ul></div>","choices":["포스퀘어(Foursquare)","맴리스터(Memristor)","비컨(Beacon)","하둡(Hadoop)"],"ans":4,"exp":{"concept":"하둡(Hadoop)은 오픈 소스 기반의 분산 컴퓨팅 플랫폼으로, 값싼 일반 PC 여러 대를 묶어 가상화된 대형 저장소를 만들고 그 안에 저장된 빅데이터를 나누어 처리한다. 분산 파일 시스템(HDFS)과 분산 처리 모델(맵리듀스, MapReduce)이 핵심이다.","choices":[{"verdict":"오답","why":"포스퀘어(Foursquare)는 사용자의 위치 정보를 기반으로 장소를 공유하는 위치 기반 소셜 네트워크 서비스다."},{"verdict":"오답","why":"멤리스터(Memristor)는 메모리(Memory)와 저항(Resistor)의 합성어로, 전류의 흐름을 기억하는 전자 소자다."},{"verdict":"오답","why":"비컨(Beacon)은 블루투스 저에너지(BLE)를 이용해 근처의 스마트 기기를 감지하고 위치 기반 정보를 보내는 근거리 통신 장치다."},{"verdict":"정답","why":"하둡은 일반 PC급 컴퓨터들로 가상화된 대형 스토리지를 만들고 빅데이터를 효율적으로 저장·처리하는 오픈 소스 분산 컴퓨팅 플랫폼이다."}],"keywords":[{"term":"하둡","desc":"오픈 소스 분산 컴퓨팅 플랫폼, 빅데이터 저장·처리"},{"term":"HDFS","desc":"하둡 분산 파일 시스템"},{"term":"맵리듀스(MapReduce)","desc":"대용량 데이터를 나누어(Map) 처리하고 합치는(Reduce) 분산 처리 모델"},{"term":"스쿱(Sqoop)","desc":"하둡과 관계형 DB 사이에서 데이터를 전송하는 도구"}],"memo":"'오픈 소스 + 분산 + 빅데이터 + 일반 PC'가 나오면 하둡이다."}},{"id":"written-2025-1-92","no":92,"unit":"정보시스템 구축 관리","q":"다음의 암호 알고리즘 가운데 성격이 다른 것은?","choices":["SHA-1","MD4","AES","MD5"],"ans":3,"exp":{"concept":"암호 알고리즘은 양방향(암호화 후 복호화 가능)과 단방향(복호화 불가)으로 나뉜다. 해시(Hash) 함수는 임의 길이의 입력을 고정 길이 값으로 바꾸는 단방향 암호이고, AES 같은 대칭키 암호는 같은 키로 암호화와 복호화를 모두 하는 양방향 암호다.","choices":[{"verdict":"오답","why":"SHA-1은 미국 NSA가 설계하고 NIST가 표준으로 채택한 해시 함수로, 단방향 암호다."},{"verdict":"오답","why":"MD4는 로널드 리베스트(Ronald Rivest)가 만든 해시 함수로, 단방향 암호다."},{"verdict":"정답","why":"AES는 블록 단위로 암호화·복호화하는 대칭키 암호 알고리즘으로, 나머지 해시 함수들과 성격이 다르다."},{"verdict":"오답","why":"MD5는 MD4를 개선한 해시 함수로, 단방향 암호다."}],"keywords":[{"term":"해시 함수","desc":"임의 길이 입력을 고정 길이로 변환하는 단방향 암호: MD4, MD5, SHA 계열 등"},{"term":"대칭키 암호","desc":"암호화·복호화 키가 같음: DES, AES, SEED, ARIA"},{"term":"비대칭키 암호","desc":"암호화·복호화 키가 다름: RSA, ECC"}],"memo":"'MD'와 'SHA'는 해시 가족이다. 나머지 하나만 고르면 된다."}},{"id":"written-2025-1-93","no":93,"unit":"정보시스템 구축 관리","q":"다음 내용이 설명하는 것으로 알맞은 것은?<div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul><li>네트워크상에서 광채널 스위치의 이점인 고속 전송과 장거리 연결 및 멀티 프로토콜 기능을 활용함</li><li>서로 다른 운영체제를 가진 여러 기종이 네트워크상에서 동일 저장장치의 데이터를 공유하도록 하여, 여러 개의 저장장치나 백업 장비를 단일화한 시스템</li></ul></div>","choices":["MBR","SAN","NAC","NIC"],"ans":2,"exp":{"concept":"SAN(Storage Area Network)은 서버와 저장 장치를 광 채널(Fibre Channel) 스위치로 연결한 저장 장치 전용 네트워크다. 서로 다른 운영체제를 쓰는 여러 서버가 같은 저장 장치를 공유할 수 있어, 흩어져 있던 저장 장치와 백업 장비를 하나로 묶어 관리할 수 있다.","choices":[{"verdict":"오답","why":"MBR(Master Boot Record)은 하드디스크의 첫 번째 섹터에 저장된 부팅 정보와 파티션 정보다."},{"verdict":"정답","why":"SAN은 광 채널 스위치의 고속 전송, 장거리 연결, 멀티 프로토콜 기능을 활용해 여러 기종이 동일 저장 장치의 데이터를 공유하도록 한 저장 장치 전용 네트워크다."},{"verdict":"오답","why":"NAC(Network Access Control)는 네트워크에 접속하는 단말의 보안 상태를 점검해 접근을 통제하는 보안 솔루션이다."},{"verdict":"오답","why":"NIC(Network Interface Card)는 컴퓨터를 네트워크에 연결하기 위한 하드웨어 장치(랜 카드)다."}],"keywords":[{"term":"DAS","desc":"Direct Attached Storage, 서버에 저장 장치를 직접 연결"},{"term":"NAS","desc":"Network Attached Storage, LAN을 통해 파일 단위로 저장 장치에 접근"},{"term":"SAN","desc":"Storage Area Network, 광 채널 스위치로 연결한 저장 장치 전용 네트워크"}],"memo":"스토리지 3종은 '직접(DAS) → 일반 네트워크(NAS) → 전용 네트워크(SAN)' 순으로 확장된다고 기억한다."}},{"id":"written-2025-1-94","no":94,"unit":"정보시스템 구축 관리","q":"COCOMO 모델을 이용한 비용 산정에 관한 설명 중 옳지 않은 것은?","choices":["규모가 같은 소프트웨어라 하더라도 그 유형에 따라 비용은 다르게 산정된다.","UFP(Unadjusted Function Point)를 계산하는 방식이다.","비용 산정 유형에는 Organic Mode, Embedded Mode, Semi-Detached Mode가 있다.","보헴이 제안한 것으로, 원시 프로그램의 규모를 기준으로 비용을 예측하는 모형이다."],"ans":2,"exp":{"concept":"COCOMO(COnstructive COst MOdel)는 보헴(Boehm)이 제안한 비용 산정 모형으로, 원시 프로그램의 규모(LOC, 코드 라인 수)를 기준으로 비용을 예측한다. 소프트웨어 유형을 조직형(Organic), 반분리형(Semi-Detached), 내장형(Embedded)으로 나누어 같은 규모라도 유형에 따라 다른 식을 적용한다.","choices":[{"verdict":"오답","why":"COCOMO는 소프트웨어 유형(조직형·반분리형·내장형)에 따라 다른 산정식을 쓰므로 같은 규모라도 비용이 다르게 산정된다. 맞는 설명이다."},{"verdict":"정답","why":"UFP(Unadjusted Function Point)를 계산하는 것은 기능 점수(FP, Function Point) 모형이다. COCOMO는 LOC(코드 라인 수)를 기준으로 한다."},{"verdict":"오답","why":"COCOMO의 비용 산정 유형은 조직형(Organic), 내장형(Embedded), 반분리형(Semi-Detached)이므로 맞는 설명이다."},{"verdict":"오답","why":"COCOMO는 보헴(Boehm)이 제안했으며 원시 프로그램의 규모(LOC)로 비용을 예측하므로 맞는 설명이다."}],"keywords":[{"term":"COCOMO","desc":"보헴이 제안, LOC 기반 비용 산정 모형"},{"term":"조직형(Organic)","desc":"5만 라인 이하, 소규모 사무 처리용"},{"term":"반분리형(Semi-Detached)","desc":"30만 라인 이하, 운영체제·DBMS 등 중간 규모"},{"term":"내장형(Embedded)","desc":"30만 라인 이상, 신호기 제어처럼 하드웨어와 밀접한 대규모 시스템"},{"term":"FP 모형","desc":"기능 점수(Function Point)로 비용을 산정, 알브레히트 제안"}],"memo":"'Point'가 들어가면 기능 점수(FP) 모형이고, COCOMO는 '라인 수'다."}},{"id":"written-2025-1-95","no":95,"unit":"정보시스템 구축 관리","q":"DoS(Denial of Service) 공격에 관한 설명 중 틀린 것은?","choices":["Land 공격은 패킷을 전송할 때 출발지 IP 주소와 목적지 IP 주소 값을 동일하게 만들어 공격 대상에게 보내는 공격 방법이다.","Ping of Death 공격은 정상 크기보다 큰 ICMP 패킷을 작은 조각(Fragment)으로 나누어 공격 대상이 조각화 된 패킷을 처리하도록 만드는 공격 방법이다.","Smurf 공격은 멀티캐스트(Multicast)를 이용하여 공격 대상이 네트워크의 임의의 시스템에 패킷을 보내도록 만드는 공격이다.","SYN Flooding은 존재하지 않는 클라이언트가 서버별로 한정된 접속 가능 공간에 접속한 것처럼 위장하여 다른 사용자가 서비스를 이용하지 못하도록 하는 것이다."],"ans":3,"exp":{"concept":"서비스 거부(DoS) 공격은 시스템 자원을 고갈시켜 정상 사용자가 서비스를 받지 못하게 하는 공격이다. 스머프(Smurf) 공격은 출발지 주소를 공격 대상의 IP로 위조한 ICMP 에코 요청 패킷을 네트워크 전체에 브로드캐스트해서, 수많은 응답이 공격 대상에게 몰리게 만든다.","choices":[{"verdict":"오답","why":"Land 공격은 출발지 IP와 목적지 IP를 공격 대상의 주소로 같게 만든 패킷을 보내, 공격 대상이 자기 자신에게 응답하며 무한 루프에 빠지게 하는 공격이므로 맞는 설명이다."},{"verdict":"오답","why":"Ping of Death는 허용 크기 이상의 큰 ICMP 패킷을 조각으로 나누어 보내, 공격 대상이 조각을 재조합하며 과부하가 걸리게 하는 공격이므로 맞는 설명이다."},{"verdict":"정답","why":"스머프 공격은 멀티캐스트가 아니라 브로드캐스트(Broadcast)를 이용한다. 출발지를 공격 대상으로 위조한 ICMP 패킷을 브로드캐스트해 네트워크의 여러 시스템이 공격 대상에게 응답을 보내게 만든다."},{"verdict":"오답","why":"SYN Flooding은 존재하지 않는 클라이언트가 접속하는 것처럼 SYN 패킷만 대량으로 보내 서버의 동시 접속 가능 공간을 가득 채워, 다른 사용자가 서비스를 받지 못하게 하는 공격이므로 맞는 설명이다."}],"keywords":[{"term":"Smurf","desc":"출발지를 위조한 ICMP 패킷을 브로드캐스트해 응답을 공격 대상에 집중"},{"term":"Ping of Death","desc":"허용 크기 이상의 ICMP 패킷을 조각내 전송"},{"term":"Land","desc":"출발지와 목적지 IP를 같게 위조"},{"term":"SYN Flooding","desc":"3-way 핸드셰이크를 완료하지 않아 접속 대기 공간을 고갈"}],"memo":"스머프 공격의 키워드는 'ICMP + 브로드캐스트'다. 멀티캐스트로 바꿔 놓은 함정에 주의한다."}},{"id":"written-2025-1-96","no":96,"unit":"정보시스템 구축 관리","q":"국내 IT 서비스의 경쟁력 강화를 목표로 개발된 것으로, 인프라 제어 및 관리 환경, 실행 환경, 개발 환경, 서비스 환경, 운영 환경으로 구성된 개방형 클라우드 컴퓨팅 플랫폼은?","choices":["KAWS","Metaverse","PaaS-TA","N2OS"],"ans":3,"exp":{"concept":"PaaS-TA는 국내 IT 서비스의 경쟁력 강화를 목표로 개발한 개방형 클라우드 컴퓨팅 플랫폼이다. 인프라 제어 및 관리 환경, 실행 환경, 개발 환경, 서비스 환경, 운영 환경으로 구성된다. 이름처럼 PaaS(Platform as a Service) 계열의 플랫폼이다.","choices":[{"verdict":"오답","why":"KAWS는 이 설명에 해당하는 출제 범위의 표준 용어가 아니다."},{"verdict":"오답","why":"메타버스(Metaverse)는 현실 세계와 같은 사회·경제·문화 활동이 이루어지는 3차원 가상 세계다."},{"verdict":"정답","why":"PaaS-TA는 국내 IT 서비스 경쟁력 강화를 위해 개발된, 다섯 가지 환경으로 구성된 개방형 클라우드 컴퓨팅 플랫폼이다."},{"verdict":"오답","why":"N2OS는 이 설명에 해당하는 출제 범위의 표준 용어가 아니다."}],"keywords":[{"term":"PaaS-TA","desc":"국내 개방형 클라우드 컴퓨팅 플랫폼"},{"term":"PaaS","desc":"Platform as a Service, 개발·실행 플랫폼을 서비스로 제공"},{"term":"IaaS·SaaS","desc":"인프라를 서비스로·소프트웨어를 서비스로 제공"}],"memo":"'국내 + 개방형 클라우드 플랫폼'이면 PaaS-TA다."}},{"id":"written-2025-1-97","no":97,"unit":"정보시스템 구축 관리","q":"다음에 제시된 프로토콜과 포트의 연결 중 잘못된 것은?","choices":["UDP 53 포트 - SNMP","UDP 111 포트 - RPC 포트매퍼","TCP 23 포트 - Telnet","UDP 69 포트 - TFTP"],"ans":1,"exp":{"concept":"잘 알려진 포트는 서비스마다 정해진 번호와 프로토콜(TCP/UDP)이 있다. DNS는 53번, SNMP는 161번(트랩은 162번)을 쓴다.","choices":[{"verdict":"정답","why":"UDP 53번은 DNS가 쓰는 포트다. SNMP는 UDP 161번(트랩 수신은 162번)을 사용하므로 잘못된 연결이다."},{"verdict":"오답","why":"RPC 포트매퍼(Portmapper)는 111번 포트를 사용하므로 맞는 연결이다."},{"verdict":"오답","why":"Telnet은 TCP 23번 포트를 사용하므로 맞는 연결이다."},{"verdict":"오답","why":"TFTP(Trivial File Transfer Protocol)는 UDP 69번 포트를 사용하므로 맞는 연결이다."}],"keywords":[{"term":"DNS","desc":"53번, 도메인 이름을 IP 주소로 변환"},{"term":"SNMP","desc":"UDP 161번(트랩 162번), 네트워크 장비 관리"},{"term":"TFTP","desc":"UDP 69번, 인증 없는 간단한 파일 전송"},{"term":"Telnet","desc":"TCP 23번, 원격 접속"}],"memo":"SNMP 161, DNS 53을 서로 바꿔 놓는 함정이 자주 나온다."}},{"id":"written-2025-1-98","no":98,"unit":"정보시스템 구축 관리","q":"정보 보안을 위한 접근통제 정책의 종류에 해당되지 않는 것은?","choices":["강제적 접근 통제","역할 기반 접근 통제","임의적 접근 통제","데이터 전환 접근 통제"],"ans":4,"exp":{"concept":"접근 통제 정책은 누가 어떤 자원에 접근할 수 있는지를 정하는 규칙으로, 임의적 접근 통제(DAC), 강제적 접근 통제(MAC), 역할 기반 접근 통제(RBAC) 세 가지가 있다.","choices":[{"verdict":"오답","why":"강제적 접근 통제(MAC, Mandatory Access Control)는 주체와 객체의 보안 등급을 비교해 시스템이 접근을 통제하는 정책이다."},{"verdict":"오답","why":"역할 기반 접근 통제(RBAC, Role Based Access Control)는 사용자의 역할(직무)에 권한을 부여해 접근을 통제하는 정책이다."},{"verdict":"오답","why":"임의적 접근 통제(DAC, Discretionary Access Control)는 데이터 소유자가 사용자 신분에 따라 접근 권한을 부여하는 정책이다."},{"verdict":"정답","why":"데이터 전환 접근 통제는 접근 통제 정책의 종류가 아니다."}],"keywords":[{"term":"DAC","desc":"신분 기반, 소유자가 권한 부여"},{"term":"MAC","desc":"규칙(보안 등급) 기반, 시스템(관리자)이 통제"},{"term":"RBAC","desc":"역할 기반, 중앙 관리자가 역할에 권한 부여"}],"memo":"접근 통제 정책은 'D·M·R' 세 가지뿐이다."}},{"id":"written-2025-1-99","no":99,"unit":"정보시스템 구축 관리","q":"위조된 매체 접근 제어(MAC) 주소를 네트워크에 지속적으로 흘려보내 스위치 MAC 주소 테이블의 저장 기능을 혼란시킴으로써 더미 허브(Dummy Hub)처럼 동작하도록 만드는 공격은?","choices":["LAN Tapping","FTP Flooding","Switch Jamming","Parsing"],"ans":3,"exp":{"concept":"스위치는 MAC 주소 테이블을 보고 프레임을 필요한 포트에만 보낸다. 스위치 재밍(Switch Jamming)은 위조한 MAC 주소를 대량으로 흘려보내 이 테이블을 가득 채워 버리는 공격이다. 테이블이 넘치면 스위치가 모든 포트로 프레임을 내보내는 더미 허브처럼 동작해, 공격자가 다른 사람의 통신을 엿볼 수 있게 된다.","choices":[{"verdict":"오답","why":"랜 탭핑(LAN Tapping)은 네트워크 선로에 장비를 직접 연결해 전송 신호를 가로채는 도청 방식으로, MAC 주소 테이블을 넘치게 하는 공격이 아니다."},{"verdict":"오답","why":"FTP Flooding은 위조 MAC 주소로 스위치를 허브처럼 만드는 공격을 가리키는 용어가 아니다."},{"verdict":"정답","why":"스위치 재밍은 위조된 MAC 주소를 지속적으로 흘려보내 스위치의 MAC 주소 테이블 저장 기능을 혼란시켜 더미 허브처럼 동작하게 하는 공격이다."},{"verdict":"오답","why":"파싱(Parsing)은 문장이나 데이터를 문법 구조에 따라 분석하는 구문 분석 작업으로, 공격 기법이 아니다."}],"keywords":[{"term":"스위치 재밍","desc":"위조 MAC 주소로 MAC 테이블을 넘치게 해 스위치를 허브처럼 만드는 공격"},{"term":"MAC 주소 테이블","desc":"스위치가 포트별 MAC 주소를 기억하는 표"},{"term":"더미 허브","desc":"들어온 신호를 모든 포트로 내보내는 단순 허브"}],"memo":"'MAC 주소 + 스위치 + 더미 허브'면 스위치 재밍(MAC 플러딩)이다."}},{"id":"written-2025-1-100","no":100,"unit":"정보시스템 구축 관리","q":"세션 하이재킹을 탐지하는 방법과 거리가 먼 것은?","choices":["비동기화 상태 탐지","FTP SYN SEGMENT 탐지","패킷의 유실 및 재전송 증가 탐지","ACK STORM 탐지"],"ans":2,"exp":{"concept":"세션 하이재킹(Session Hijacking)은 서버와 클라이언트 사이에 이미 인증된 TCP 세션을 가로채는 공격이다. 가로채는 과정에서 시퀀스 번호가 어긋나므로, 비동기화 상태, ACK 패킷 폭주(ACK Storm), 패킷 유실과 재전송 증가, 예상치 못한 접속 리셋 등을 탐지해 공격을 알아낸다.","choices":[{"verdict":"오답","why":"공격자가 세션을 가로채면 서버와 클라이언트의 시퀀스 번호가 어긋나는 비동기화 상태가 생기므로, 이를 탐지하는 것은 세션 하이재킹 탐지 방법이다."},{"verdict":"정답","why":"FTP SYN SEGMENT 탐지는 세션 하이재킹을 탐지하는 방법이 아니다."},{"verdict":"오답","why":"시퀀스 번호가 어긋나면서 패킷 유실과 재전송이 늘어나므로, 이를 탐지하는 것은 세션 하이재킹 탐지 방법이다."},{"verdict":"오답","why":"어긋난 시퀀스 번호를 바로잡으려는 ACK 패킷이 폭주하는 ACK Storm을 탐지하는 것은 세션 하이재킹 탐지 방법이다."}],"keywords":[{"term":"세션 하이재킹","desc":"인증된 TCP 세션을 가로채는 공격"},{"term":"비동기화 상태","desc":"서버와 클라이언트의 시퀀스 번호가 어긋난 상태"},{"term":"ACK Storm","desc":"시퀀스 번호 불일치로 ACK 패킷이 계속 오가는 현상"}],"memo":"세션 하이재킹 탐지는 '비동기화·ACK Storm·재전송 증가·접속 리셋' 네 가지다."}}]};